/* canada-quiz.com — Alberta Class 7 practice data
   Test format, and 160 original bilingual questions (80 road signs + 80 rules).
   All wording is our own. Free practice site, not affiliated with any government.
   The quiz code lives in js/driving-engine.js and never changes per province. */
window.CQ_DRIVE_Q = [];
(window.CQ_DRIVE_Q = window.CQ_DRIVE_Q || []).push(
  { id:"abs1", sec:"signs", sign:"stop",
    en:{ q:"You reach this sign at a country intersection where tall crops block your view to the left. What is the correct way to handle it?", a:["Sound your horn and roll slowly through the intersection without stopping","Stop only if you can see a vehicle coming toward you","Stop first, then edge forward until you can see, then go when clear","Speed up so you spend less time inside the intersection"], e:"The full stop comes first, then a slow creep to a spot where you can actually see the whole road." },
    fr:{ q:"Vous arrivez à ce panneau à une intersection de campagne où de grandes cultures bloquent votre vue vers la gauche. Quelle est la bonne façon de faire ?", a:["Klaxonner et traverser lentement l'intersection sans vous arrêter","Vous arrêter seulement si vous voyez un véhicule venir vers vous","Vous arrêter d'abord, avancer doucement jusqu'à ce que vous voyiez, puis passer quand c'est libre","Accélérer pour passer moins de temps dans l'intersection"], e:"L'arrêt complet vient en premier, puis on avance doucement jusqu'à un endroit d'où on voit vraiment toute la route." },
    c:2 },
  { id:"abs2", sec:"signs", sign:"yield",
    en:{ q:"This sign faces you on a ramp joining a busy highway. What does it require?", a:["Slow down, give way to traffic already on the highway, and stop if you must","Stop completely at the end of the ramp every single time","Keep your speed and expect the highway traffic to open up a gap for you","Signal once and move over as soon as the ramp lane runs out"], e:"Giving way means the other traffic goes first, and you fit in only when there is a real gap." },
    fr:{ q:"Ce panneau vous fait face sur une bretelle qui rejoint une autoroute achalandée. Qu'exige-t-il ?", a:["Ralentir, céder le passage aux véhicules déjà sur l'autoroute et vous arrêter au besoin","Vous arrêter complètement au bout de la bretelle chaque fois","Garder votre vitesse et attendre que la circulation de l'autoroute vous laisse un espace","Mettre votre clignotant et vous insérer dès que la voie d'accès se termine"], e:"Céder le passage veut dire que les autres passent en premier, et vous vous insérez seulement quand il y a un vrai espace." },
    c:0 },
  { id:"abs3", sec:"signs", sign:"speed-50",
    en:{ q:"This sign is posted on a street where blowing snow has cut your view to a few car lengths. What speed is right?", a:["The posted number, because it is the legal speed in every kind of weather","Ten kilometres per hour over it, since traffic is light","Whatever speed the vehicle in front of you is holding","Slower than the number shown, because it is a maximum for good conditions"], e:"A posted limit is the most you may drive in perfect conditions, never a promise that the speed is safe today." },
    fr:{ q:"Ce panneau est installé dans une rue où la poudrerie réduit votre vue à quelques longueurs de voiture. Quelle vitesse convient ?", a:["Le chiffre affiché, car c'est la vitesse légale par n'importe quel temps","Dix kilomètres à l'heure de plus, puisqu'il y a peu de circulation","La vitesse que garde le véhicule devant vous","Moins que le chiffre affiché, car c'est un maximum pour de bonnes conditions"], e:"Une limite affichée est le maximum permis dans des conditions parfaites, jamais une garantie que cette vitesse est sûre aujourd'hui." },
    c:3 },
  { id:"abs4", sec:"signs", sign:"speed-limit-begins",
    en:{ q:"From what point does the speed shown on this sign apply?", a:["From the next intersection you pass","From the sign onward, until another speed sign changes it","Only on the block where the sign is standing","From one kilometre before the sign to one kilometre after"], e:"Speed signs take effect where they stand and stay in force until a new sign says otherwise." },
    fr:{ q:"À partir de quel point la vitesse indiquée sur ce panneau s'applique-t-elle ?", a:["À partir de la prochaine intersection que vous franchissez","À partir du panneau, jusqu'à ce qu'un autre panneau change la vitesse","Seulement dans le pâté de maisons où se trouve le panneau","D'un kilomètre avant le panneau à un kilomètre après"], e:"Les panneaux de vitesse s'appliquent dès l'endroit où ils sont plantés et restent en vigueur jusqu'au prochain panneau." },
    c:1 },
  { id:"abs5", sec:"signs", sign:"no-entry",
    en:{ q:"You are looking for a way into a parkade and see this sign at one of the ramps. What does it tell you?", a:["The ramp is for permit holders only","The ramp is closed outside of normal business hours","You must not drive in here, so find another way in","You may enter but only at walking speed"], e:"This sign often marks an exit ramp, where driving in would put you nose to nose with traffic coming out." },
    fr:{ q:"Vous cherchez l'entrée d'un stationnement étagé et vous voyez ce panneau à l'une des rampes. Que vous indique-t-il ?", a:["La rampe est réservée aux détenteurs d'un permis","La rampe est fermée en dehors des heures normales d'ouverture","Vous ne devez pas entrer ici, trouvez une autre entrée","Vous pouvez entrer, mais à la vitesse d'un piéton"], e:"Ce panneau marque souvent une rampe de sortie, où entrer vous mettrait nez à nez avec les véhicules qui sortent." },
    c:2 },
  { id:"abs6", sec:"signs", sign:"one-way",
    en:{ q:"You want to turn onto a cross street and this sign there points to the right. What does it tell you?", a:["Traffic on that street takes turns in each direction","Traffic on that street moves only in the direction of the arrow","That street bends to the right a short way ahead","Parking along that street is allowed on the right hand side only"], e:"Turning against the arrow would send you straight into traffic coming the other way." },
    fr:{ q:"Vous voulez tourner dans une rue transversale et ce panneau y pointe vers la droite. Que vous indique-t-il ?", a:["La circulation dans cette rue alterne dans les deux sens","La circulation dans cette rue va seulement dans le sens de la flèche","Cette rue tourne vers la droite un peu plus loin","Le stationnement dans cette rue est permis du côté droit seulement"], e:"Tourner contre la flèche vous enverrait droit dans les véhicules qui arrivent en sens inverse." },
    c:1 },
  { id:"abs7", sec:"signs", sign:"no-left-turn",
    en:{ q:"You meant to turn left here but this sign stops you. What is the simplest legal way to reach that street?", a:["Wait for a gap in traffic when no other driver is watching you","Make a turn to go back just past the corner","Turn left from the lane beside you instead","Carry on and go around the block with three right turns"], e:"Three rights make a left, and it keeps you out of the turn the sign was put there to prevent." },
    fr:{ q:"Vous vouliez tourner à gauche ici, mais ce panneau vous en empêche. Quelle est la façon légale la plus simple d'atteindre cette rue ?", a:["Attendre un espace dans la circulation quand aucun autre conducteur ne regarde","Faire demi-tour juste après le coin","Tourner à gauche à partir de la voie voisine","Continuer et faire le tour du pâté de maisons avec trois virages à droite"], e:"Trois virages à droite valent un virage à gauche, et cela évite le virage que le panneau interdit." },
    c:3 },
  { id:"abs8", sec:"signs", sign:"no-right-turn",
    en:{ q:"This sign has no times or days written on it. When does it apply?", a:["At every hour of every day","Only during weekday rush hours","Only when the traffic light is red","Only when school is in session"], e:"A restriction sign with no time panel under it is in force around the clock." },
    fr:{ q:"Ce panneau ne porte aucune heure ni aucun jour. Quand s'applique-t-il ?", a:["À toute heure, tous les jours","Seulement aux heures de pointe en semaine","Seulement quand le feu de circulation est rouge","Seulement pendant l'année scolaire"], e:"Un panneau d'interdiction sans panonceau d'heures s'applique en tout temps." },
    c:0 },
  { id:"abs9", sec:"signs", sign:"no-u-turn",
    en:{ q:"You have driven past your turnoff on a divided highway and see this sign at the next crossover. What should you do?", a:["Turn around anyway if no traffic is in sight","Back up along the shoulder to your turnoff","Keep going to the next interchange and turn around there","Stop on the shoulder and wait for a gap to swing back around"], e:"Crossovers on divided highways are often left for maintenance and emergency vehicles only." },
    fr:{ q:"Vous avez dépassé votre sortie sur une route à chaussées séparées et vous voyez ce panneau au prochain passage central. Que devez-vous faire ?", a:["Faire demi-tour quand même si aucun véhicule n'est en vue","Reculer sur l'accotement jusqu'à votre sortie","Continuer jusqu'au prochain échangeur et faire demi-tour là-bas","Vous arrêter sur l'accotement et attendre un espace pour faire demi-tour"], e:"Les passages centraux des routes à chaussées séparées sont souvent réservés à l'entretien et aux véhicules d'urgence." },
    c:2 },
  { id:"abs10", sec:"signs", sign:"turn-left-only",
    en:{ q:"You are in the lane marked by this sign but you have changed your mind and want to go straight. What must you do?", a:["Go straight anyway, since the sign is only a suggestion here","Turn left as the sign says, then find another route","Stop and wave the drivers behind you around","Reverse and move into the next lane over"], e:"Once you are in a turn-only lane you must complete that turn, because a last second change surprises everyone." },
    fr:{ q:"Vous êtes dans la voie indiquée par ce panneau, mais vous avez changé d'idée et voulez aller tout droit. Que devez-vous faire ?", a:["Aller tout droit quand même, car le panneau n'est qu'une suggestion","Tourner à gauche comme l'indique le panneau, puis trouver un autre chemin","Vous arrêter et faire signe aux conducteurs derrière de vous contourner","Reculer et vous placer dans la voie voisine"], e:"Dans une voie réservée à un virage, il faut faire ce virage, car un changement de dernière seconde surprend tout le monde." },
    c:1 },
  { id:"abs11", sec:"signs", sign:"no-parking",
    en:{ q:"You leave your vehicle at the curb under this sign for five minutes to run into a shop. Is that allowed?", a:["Yes, as long as you leave your hazard lights flashing the whole time","Yes, anything under fifteen minutes is fine","Yes, as long as you stay on the same block","No, leaving the vehicle here is parking no matter how short"], e:"You may pause here to let people or goods in and out, but the moment you walk away it becomes parking." },
    fr:{ q:"Vous laissez votre véhicule au bord du trottoir sous ce panneau pendant cinq minutes pour entrer dans un magasin. Est-ce permis ?", a:["Oui, tant que vous laissez vos feux de détresse allumés tout ce temps","Oui, moins de quinze minutes ne pose pas de problème","Oui, tant que vous restez dans le même pâté de maisons","Non, laisser le véhicule ici est du stationnement, même pour peu de temps"], e:"Vous pouvez vous arrêter brièvement pour faire monter ou descendre des personnes ou des marchandises, mais dès que vous partez à pied, c'est du stationnement." },
    c:3 },
  { id:"abs12", sec:"signs", sign:"no-stopping",
    en:{ q:"Traffic backs up and the vehicle ahead leaves you stopped under this sign. Have you broken the rule?", a:["No, being held by traffic or a signal is not what this sign forbids","Yes, and you must reverse until your vehicle is clear of the sign area","Yes, any stop under this sign is against the rule","No, because the sign only applies after dark"], e:"This sign bans stopping by choice, such as waiting for a friend, which is different from being stuck in a line of traffic." },
    fr:{ q:"La circulation est bloquée et le véhicule devant vous laisse votre voiture immobilisée sous ce panneau. Avez-vous enfreint la règle ?", a:["Non, être retenu par la circulation ou un feu n'est pas ce que ce panneau interdit","Oui, et vous devez reculer jusqu'à ce que votre véhicule dépasse le panneau","Oui, tout arrêt sous ce panneau est interdit","Non, parce que le panneau s'applique seulement la nuit"], e:"Ce panneau interdit l'arrêt volontaire, comme attendre un ami, ce qui est différent d'être coincé dans une file." },
    c:0 },
  { id:"abs13", sec:"signs", sign:"no-passing",
    en:{ q:"A slow gravel truck is crawling along ahead of you where this sign is posted. What should you do?", a:["Pass on the shoulder to the right of the truck","Flash your headlights until the truck moves over to let you by","Stay well back and wait until the restriction ends","Pass quickly while the road ahead looks empty"], e:"These signs go up where the road hides oncoming traffic, so what looks empty may not be. 🚧" },
    fr:{ q:"Un camion de gravier avance lentement devant vous là où ce panneau est installé. Que devez-vous faire ?", a:["Dépasser par l'accotement, à droite du camion","Faire des appels de phares jusqu'à ce que le camion se range pour vous laisser passer","Rester bien derrière et attendre la fin de l'interdiction","Dépasser vite pendant que la route devant semble vide"], e:"Ces panneaux sont posés là où la route cache les véhicules qui arrivent, alors ce qui semble vide ne l'est pas forcément. 🚧" },
    c:2 },
  { id:"abs14", sec:"signs", sign:"keep-right",
    en:{ q:"The road splits around a raised island and this sign is on the island. Which path is correct?", a:["Either side, whichever has less traffic","Pass to the right of the island","Pass to the left of the island","Stop before the island and let oncoming traffic clear"], e:"Islands split traffic, and taking the wrong side puts you into vehicles coming the other way." },
    fr:{ q:"La route se sépare autour d'un îlot surélevé et ce panneau se trouve sur l'îlot. Quel chemin est le bon ?", a:["Un côté ou l'autre, celui qui a le moins de circulation","Passer à droite de l'îlot","Passer à gauche de l'îlot","Vous arrêter avant l'îlot et laisser passer les véhicules en sens inverse"], e:"Les îlots séparent la circulation, et prendre le mauvais côté vous place face aux véhicules qui arrivent." },
    c:1 },
  { id:"abs15", sec:"signs", sign:"no-trucks",
    en:{ q:"You are driving a loaded delivery truck and this sign is posted at the entrance to a quiet street. What does it mean for you?", a:["You may use the street below thirty kilometres per hour","You may use the street if your load is light","You may use the street outside of school hours","You must find another route that allows trucks"], e:"Towns keep heavy traffic off certain streets to protect both the pavement and the peace and quiet." },
    fr:{ q:"Vous conduisez un camion de livraison chargé et ce panneau est installé à l'entrée d'une rue tranquille. Que signifie-t-il pour vous ?", a:["Vous pouvez emprunter la rue à moins de trente kilomètres à l'heure","Vous pouvez emprunter la rue si votre chargement est léger","Vous pouvez emprunter la rue en dehors des heures d'école","Vous devez trouver un autre chemin ouvert aux camions"], e:"Les municipalités éloignent la circulation lourde de certaines rues pour protéger la chaussée et la tranquillité." },
    c:3 },
  { id:"abs16", sec:"signs", sign:"hov-lane",
    en:{ q:"You are driving with two friends in the vehicle and see this sign over a lane. What does it let you do?", a:["Use that lane, because you carry enough people to qualify","Use that lane only between the rush hours","Use any lane except that one","Use that lane only when you are not towing anything behind you"], e:"These lanes reward sharing a ride, and the sign shows the smallest number of people the vehicle must carry." },
    fr:{ q:"Vous conduisez avec deux amis à bord et vous voyez ce panneau au-dessus d'une voie. Que vous permet-il ?", a:["Utiliser cette voie, car vous transportez assez de personnes","Utiliser cette voie seulement entre les heures de pointe","Utiliser toutes les voies sauf celle-là","Utiliser cette voie seulement si vous ne tirez rien derrière vous"], e:"Ces voies récompensent le covoiturage, et le panneau indique le nombre minimal de personnes à bord." },
    c:0 },
  { id:"abs17", sec:"signs", sign:"stop-school-bus",
    en:{ q:"On a two-lane rural highway a bus with this sign on the back comes toward you with red lights flashing. What must you do?", a:["Slow to thirty and pass the bus carefully","Keep going, since the rule is only for drivers behind the bus","Stop and wait until the lights stop flashing","Move onto the shoulder and continue slowly"], e:"On a road with no median, traffic in both directions stops, because children may cross in front of the bus." },
    fr:{ q:"Sur une route rurale à deux voies, un autobus portant ce panneau à l'arrière vient vers vous, feux rouges clignotants. Que devez-vous faire ?", a:["Ralentir à trente et dépasser l'autobus avec prudence","Continuer, car la règle vise seulement les conducteurs derrière l'autobus","Vous arrêter et attendre que les feux cessent de clignoter","Vous ranger sur l'accotement et continuer lentement"], e:"Sur une route sans terre-plein, la circulation s'arrête dans les deux sens, car des enfants peuvent traverser devant l'autobus." },
    c:2 },
  { id:"abs18", sec:"signs", sign:"ped-crossover",
    en:{ q:"The driver in the lane beside you has stopped at this crossing. What should you do?", a:["Pass carefully, because you can see the crosswalk is empty","Stop as well, since someone you cannot see may be crossing","Sound your horn to warn anyone in the crosswalk","Continue if nobody has stepped off the curb on your side"], e:"The stopped vehicle blocks your view, and passing it is one of the most dangerous moves a driver can make." },
    fr:{ q:"Le conducteur dans la voie à côté de vous s'est arrêté à ce passage. Que devez-vous faire ?", a:["Dépasser avec prudence, car vous voyez que le passage est vide","Vous arrêter aussi, car une personne que vous ne voyez pas peut traverser","Klaxonner pour avertir les personnes sur le passage","Continuer si personne n'a quitté le trottoir de votre côté"], e:"Le véhicule arrêté vous cache la vue, et le dépasser est l'une des manoeuvres les plus dangereuses qui soient." },
    c:1 },
  { id:"abs19", sec:"signs", sign:"community-safety-zone",
    en:{ q:"How are traffic fines treated along the stretch of road that starts at this sign?", a:["They are the same as anywhere else in the province","They are replaced by a written warning for a driver's first offence","They are lowered because the speeds there are lower","They can be much higher than for the same offence elsewhere"], e:"These zones cover places where people are close to traffic, so the penalties are raised to make drivers pay attention." },
    fr:{ q:"Comment traite-t-on les amendes de circulation sur le tronçon de route qui commence à ce panneau ?", a:["Elles sont les mêmes que partout ailleurs dans la province","Elles sont remplacées par un avertissement écrit à la première infraction","Elles sont réduites parce que les vitesses y sont plus basses","Elles peuvent être bien plus élevées que pour la même infraction ailleurs"], e:"Ces zones couvrent des endroits où les gens sont près de la circulation, alors les sanctions sont augmentées pour attirer l'attention des conducteurs." },
    c:3 },
  { id:"abs20", sec:"signs", sign:"info-hospital",
    en:{ q:"A passenger needs care and you see this sign on a highway. What is it telling you?", a:["The route to follow to reach medical services","That an ambulance may pull onto the road here","That a first aid kit is required in your vehicle","That a rest area is coming up shortly"], e:"Blue information signs point to services, and this is one of the most useful ones to remember." },
    fr:{ q:"Un passager a besoin de soins et vous voyez ce panneau sur une route. Que vous indique-t-il ?", a:["Le chemin à suivre pour atteindre des services médicaux","Qu'une ambulance peut s'engager sur la route ici","Qu'une trousse de premiers soins est obligatoire dans votre véhicule","Qu'une halte routière arrive bientôt"], e:"Les panneaux bleus d'information indiquent des services, et celui-ci est l'un des plus utiles à retenir." },
    c:0 },
  { id:"abs21", sec:"signs", sign:"info-gas",
    en:{ q:"You are on a long prairie highway with a quarter tank left and this sign appears. What does it promise?", a:["A weigh station for commercial vehicles","A place to check your tire pressure only","A truck stop reserved for commercial traffic","Fuel is available at the exit or town ahead"], e:"On the prairies the next town can be a very long way off, so top up whenever a service sign gives you the chance." },
    fr:{ q:"Vous roulez sur une longue route des Prairies avec un quart de réservoir et ce panneau apparaît. Que promet-il ?", a:["Un poste de pesée pour les véhicules commerciaux","Un endroit pour vérifier la pression des pneus seulement","Un relais réservé aux camionneurs","Du carburant est offert à la sortie ou au village qui vient"], e:"Dans les Prairies, le prochain village peut être très loin, alors faites le plein dès qu'un panneau de service vous en donne l'occasion." },
    c:3 },
  { id:"abs22", sec:"signs", sign:"info-exit",
    en:{ q:"You see this sign and the turnoff it names is yours. What should you already have done?", a:["Turned on your hazard lights","Slowed to half the posted speed","Moved into the right lane in good time","Sounded your horn to warn other drivers"], e:"Lane changes belong well before the ramp, because cutting across at the last moment causes crashes at exits." },
    fr:{ q:"Vous voyez ce panneau et la sortie qu'il nomme est la vôtre. Qu'auriez-vous déjà dû faire ?", a:["Allumer vos feux de détresse","Ralentir à la moitié de la vitesse affichée","Vous placer dans la voie de droite bien à l'avance","Klaxonner pour avertir les autres conducteurs"], e:"Les changements de voie se font bien avant la bretelle, car couper au dernier moment cause des collisions aux sorties." },
    c:2 },
  { id:"abs23", sec:"signs", sign:"info-accessible",
    en:{ q:"You park in a space marked with this sign using a valid permit. Where must the permit be?", a:["Displayed so it can be read from outside the vehicle","Locked in the glove box with your registration","Kept in your wallet in case an officer asks you to show it","Taped to the driver's side rear window"], e:"The permit only does its job if an officer can read it without opening your vehicle." },
    fr:{ q:"Vous stationnez dans une place marquée par ce panneau avec une vignette valide. Où doit se trouver la vignette ?", a:["Bien en vue, de façon à être lue de l'extérieur du véhicule","Enfermée dans le coffre à gants avec l'immatriculation","Gardée dans votre portefeuille au cas où un agent vous la demande","Collée sur la vitre arrière du côté du conducteur"], e:"La vignette ne sert à rien si un agent ne peut pas la lire sans ouvrir votre véhicule." },
    c:0 },
  { id:"abs24", sec:"signs", sign:"warn-curve-right",
    en:{ q:"Where should you do your braking for the curve shown on this sign?", a:["In the middle of the curve, where you can feel the grip","After the curve, once the road straightens out","Only if another vehicle is coming the other way","Before you enter the curve, while still going straight"], e:"Braking inside a curve upsets the tires, so slow down first and then steer smoothly through." },
    fr:{ q:"Où devez-vous freiner pour la courbe annoncée par ce panneau ?", a:["Au milieu de la courbe, là où on sent l'adhérence","Après la courbe, une fois la route redevenue droite","Seulement si un véhicule arrive en sens inverse","Avant d'entrer dans la courbe, pendant que vous roulez droit"], e:"Freiner dans une courbe déstabilise les pneus, alors on ralentit d'abord et on tourne ensuite en douceur." },
    c:3 },
  { id:"abs25", sec:"signs", sign:"warn-slippery",
    en:{ q:"This sign stands near a bridge on a cold morning. Why is the bridge deck a special worry?", a:["Bridges are always built with smoother pavement","Bridge decks freeze before the rest of the road does","Bridges collect more loose gravel than other surfaces","Bridges are narrower than the road on each side"], e:"Cold air flows under a bridge as well as over it, so a bridge can be icy while the road looks perfectly fine. ❄️" },
    fr:{ q:"Ce panneau se trouve près d'un pont par un matin froid. Pourquoi le tablier du pont est-il une inquiétude particulière ?", a:["Les ponts sont toujours construits avec un revêtement plus lisse","Le tablier d'un pont gèle avant le reste de la route","Les ponts accumulent plus de gravier que les autres surfaces","Les ponts sont plus étroits que la route de chaque côté"], e:"L'air froid passe sous le pont autant que dessus, alors un pont peut être glacé même si la route semble parfaite. ❄️" },
    c:1 },
  { id:"abs26", sec:"signs", sign:"warn-steep-hill",
    en:{ q:"You are driving a heavy load down the long mountain grade this sign warns about. How do you best control your speed?", a:["Hold the brake pedal down steadily for the whole descent","Shift into neutral and coast to save fuel","Shift to a lower gear and use the brakes lightly","Turn the engine off and let gravity do the work"], e:"Riding the brakes down a long hill overheats them, while a low gear lets the engine hold you back." },
    fr:{ q:"Vous descendez avec une lourde charge la longue pente de montagne annoncée par ce panneau. Comment contrôler au mieux votre vitesse ?", a:["Garder la pédale de frein enfoncée sans arrêt pendant toute la descente","Passer au point mort et descendre en roue libre pour économiser du carburant","Passer à une vitesse inférieure et freiner légèrement","Couper le moteur et laisser la gravité faire le travail"], e:"Freiner sans arrêt dans une longue descente fait surchauffer les freins, tandis qu'un rapport bas laisse le moteur vous retenir." },
    c:2 },
  { id:"abs27", sec:"signs", sign:"warn-narrow-bridge",
    en:{ q:"You and an oncoming vehicle reach the bridge this sign warns of at the same moment. What is the safe move?", a:["Slow down and be ready to let the other vehicle come through first","Speed up so that you are onto the bridge well before the other driver","Move onto the shoulder and cross beside them","Sound your horn and hold your lane position"], e:"A narrow bridge leaves no room for mistakes, so the safest driver is the one willing to wait." },
    fr:{ q:"Un véhicule et vous arrivez en même temps au pont annoncé par ce panneau. Quelle est la manoeuvre sécuritaire ?", a:["Ralentir et être prêt à laisser passer l'autre véhicule en premier","Accélérer pour être sur le pont bien avant l'autre conducteur","Vous ranger sur l'accotement et traverser à côté de lui","Klaxonner et garder votre position dans la voie"], e:"Un pont étroit ne laisse aucune place à l'erreur, alors le conducteur le plus prudent est celui qui accepte d'attendre." },
    c:0 },
  { id:"abs28", sec:"signs", sign:"warn-two-way",
    en:{ q:"You have been driving on a divided highway and this sign appears. Why does it change how you drive?", a:["Because the posted speed limit always drops by twenty here","Because oncoming traffic now shares the same road surface","Because the shoulder becomes a driving lane","Because passing is now allowed at any point"], e:"Once the median ends there is nothing between you and traffic coming the other way, so passing gets far riskier." },
    fr:{ q:"Vous rouliez sur une route à chaussées séparées et ce panneau apparaît. Pourquoi change-t-il votre façon de conduire ?", a:["Parce que la limite de vitesse affichée baisse toujours de vingt ici","Parce que les véhicules en sens inverse partagent maintenant la même chaussée","Parce que l'accotement devient une voie de circulation","Parce que le dépassement est maintenant permis partout"], e:"Dès que le terre-plein se termine, plus rien ne vous sépare des véhicules qui arrivent, alors dépasser devient bien plus risqué." },
    c:1 },
  { id:"abs29", sec:"signs", sign:"warn-merge",
    en:{ q:"This sign warns that another road is about to join yours. What is the safe and courteous response?", a:["Speed up to get past the joining point first","Move over onto the shoulder to leave the whole lane free","Stop at the joining point and wave drivers in","Adjust your speed or change lanes to open a gap"], e:"Merging works when both drivers adjust a little, and nobody has to stop if the gaps are made early." },
    fr:{ q:"Ce panneau annonce qu'une autre route va rejoindre la vôtre. Quelle est la réaction sécuritaire et courtoise ?", a:["Accélérer pour passer le point de jonction en premier","Vous ranger sur l'accotement pour libérer toute la voie","Vous arrêter au point de jonction et faire signe aux autres d'entrer","Ajuster votre vitesse ou changer de voie pour ouvrir un espace"], e:"L'insertion fonctionne quand chacun s'ajuste un peu, et personne n'a à s'arrêter si les espaces se créent tôt." },
    c:3 },
  { id:"abs30", sec:"signs", sign:"warn-signal-ahead",
    en:{ q:"This sign is on a highway where the road dips and rises ahead. Why is it there?", a:["Because traffic lights are ahead that you cannot see yet","Because the road ahead is controlled by a traffic control person","Because a vehicle inspection point is set up ahead","Because the road ahead has no shoulder"], e:"Warning signs go where a hill, a curve or trees hide what is coming, which gives you time to slow down." },
    fr:{ q:"Ce panneau est sur une route où la chaussée descend puis remonte devant vous. Pourquoi est-il là ?", a:["Parce que des feux de circulation que vous ne voyez pas encore approchent","Parce qu'un signaleur dirige la circulation plus loin","Parce qu'un point de vérification des véhicules est installé plus loin","Parce que la route devant n'a pas d'accotement"], e:"Les panneaux d'avertissement sont posés là où une côte, une courbe ou des arbres cachent ce qui arrive, ce qui vous donne le temps de ralentir." },
    c:0 },
  { id:"abs31", sec:"signs", sign:"warn-stop-ahead",
    en:{ q:"You see this sign on a gravel road while travelling at highway speed. What should you begin doing?", a:["Turn on your four way flashers and hold your speed to the corner","Move to the middle of the road for better grip","Slow down early so you can stop smoothly at the intersection","Sound your horn as you reach the intersection"], e:"Gravel needs much more room to stop, so start slowing the moment the warning appears." },
    fr:{ q:"Vous voyez ce panneau sur une route de gravier alors que vous roulez à la vitesse de l'autoroute. Que devez-vous commencer à faire ?", a:["Allumer vos feux de détresse et garder votre vitesse jusqu'au coin","Vous placer au centre de la route pour une meilleure adhérence","Ralentir tôt pour vous arrêter en douceur à l'intersection","Klaxonner en arrivant à l'intersection"], e:"Sur le gravier, il faut beaucoup plus de distance pour s'arrêter, alors ralentissez dès que l'avertissement apparaît." },
    c:2 },
  { id:"abs32", sec:"signs", sign:"warn-school-zone",
    en:{ q:"This sign marks the start of a zone. What is the biggest reason to slow down here?", a:["Because school buses park along both sides of the road here","Because children may step out without checking for traffic","Because the pavement is rougher in these areas","Because parking rules change inside the zone"], e:"Young children judge speed and distance poorly, so the driver has to do the thinking for both. 🎒" },
    fr:{ q:"Ce panneau marque le début d'une zone. Quelle est la principale raison de ralentir ici ?", a:["Parce que des autobus scolaires se garent des deux côtés de la rue","Parce que des enfants peuvent surgir sans regarder la circulation","Parce que la chaussée est plus abîmée dans ces secteurs","Parce que les règles de stationnement changent dans la zone"], e:"Les jeunes enfants jugent mal la vitesse et la distance, alors le conducteur doit penser pour deux. 🎒" },
    c:1 },
  { id:"abs33", sec:"signs", sign:"warn-playground",
    en:{ q:"It is a quiet evening and you see no children near this sign. How should you drive?", a:["At normal speed, since the zone applies in daytime only","At normal speed, since the zone applies on school days only","Faster than the zone speed but slower than the street speed","At the zone speed, because a child can appear in a second"], e:"Playground zones run well into the evening, and children can dart out from between parked vehicles." },
    fr:{ q:"C'est une soirée tranquille et vous ne voyez aucun enfant près de ce panneau. Comment devez-vous conduire ?", a:["À la vitesse normale, car la zone s'applique le jour seulement","À la vitesse normale, car la zone s'applique les jours d'école seulement","Plus vite que la vitesse de la zone, mais moins vite que celle de la rue","À la vitesse de la zone, car un enfant peut surgir en une seconde"], e:"Les zones de jeu s'appliquent jusque tard en soirée, et un enfant peut surgir entre deux véhicules stationnés." },
    c:3 },
  { id:"abs34", sec:"signs", sign:"warn-deer",
    en:{ q:"You pass this sign at dusk on a rural highway. Besides slowing down, what helps most?", a:["Scanning both ditches and expecting more than one animal","Driving with your high beams switched off at all times","Staying in the left lane wherever there are two","Sounding your horn steadily until you are safely past the area"], e:"These animals travel in groups, so where one crosses, another is usually right behind. 🦌" },
    fr:{ q:"Vous passez devant ce panneau au crépuscule sur une route rurale. À part ralentir, qu'est-ce qui aide le plus ?", a:["Balayer les deux fossés du regard et vous attendre à plus d'un animal","Rouler avec les feux de route éteints en tout temps","Rester dans la voie de gauche là où il y en a deux","Klaxonner sans arrêt jusqu'à ce que vous ayez dépassé le secteur"], e:"Ces animaux se déplacent en groupe, alors là où l'un traverse, un autre suit presque toujours. 🦌" },
    c:0 },
  { id:"abs35", sec:"signs", sign:"warn-moose",
    en:{ q:"Why does the animal on this sign create a special danger compared with a smaller one?", a:["It is faster than a vehicle over short distances","It is drawn toward the sound of engines","It is so tall that its body can reach the windshield","It moves about only during the daylight hours"], e:"Its long legs put most of its weight at windshield height, which is why drivers slow right down where these signs stand." },
    fr:{ q:"Pourquoi l'animal de ce panneau est-il plus dangereux qu'un animal plus petit ?", a:["Il court plus vite qu'un véhicule sur de courtes distances","Il est attiré par le bruit des moteurs","Il est si grand que son corps peut atteindre le pare-brise","Il se déplace uniquement pendant le jour"], e:"Ses longues pattes placent l'essentiel de son poids à la hauteur du pare-brise, d'où l'importance de bien ralentir près de ces panneaux." },
    c:2 },
  { id:"abs36", sec:"signs", sign:"warn-railway",
    en:{ q:"This sign appears well before the tracks. What is it asking of you?", a:["Stop right where the sign is standing","Slow down, look and listen, and be ready to stop","Speed up so that you clear the railway tracks quickly","Change lanes to the left before the tracks"], e:"The advance sign buys you time, while the decision to stop happens at the tracks themselves. 🚂" },
    fr:{ q:"Ce panneau apparaît bien avant la voie ferrée. Que vous demande-t-il ?", a:["Vous arrêter à l'endroit même où se trouve le panneau","Ralentir, regarder, écouter et être prêt à vous arrêter","Accélérer pour franchir la voie ferrée rapidement","Changer de voie vers la gauche avant la voie ferrée"], e:"Le panneau avancé vous donne du temps, tandis que la décision de vous arrêter se prend à la voie ferrée même. 🚂" },
    c:1 },
  { id:"abs37", sec:"signs", sign:"warn-crossbuck",
    en:{ q:"A train is coming and this sign stands at the crossing. Where must you stop?", a:["Right beside the sign post","Anywhere at all before the first rail","At least two metres from the nearest rail","At least five metres from the nearest rail"], e:"A train is wider than the rails it rides on, so a stop that feels close enough often is not." },
    fr:{ q:"Un train approche et ce panneau se trouve au passage à niveau. Où devez-vous vous arrêter ?", a:["Juste à côté du poteau du panneau","N'importe où avant le premier rail","À au moins deux mètres du rail le plus proche","À au moins cinq mètres du rail le plus proche"], e:"Un train est plus large que les rails sur lesquels il roule, alors un arrêt qui semble assez loin ne l'est souvent pas." },
    c:3 },
  { id:"abs38", sec:"signs", sign:"warn-roundabout",
    en:{ q:"This sign warns of what is ahead. Who has the right of way once you get there?", a:["Traffic that is already going around the circle","The vehicle that arrives at the highest speed","Traffic entering from the largest road","The vehicle on your right at every entry"], e:"You give way on the way in and keep moving once you are around, which is what keeps the circle flowing." },
    fr:{ q:"Ce panneau annonce ce qui s'en vient. Qui a la priorité une fois sur place ?", a:["Les véhicules qui circulent déjà dans l'anneau","Le véhicule qui arrive à la plus grande vitesse","Les véhicules qui entrent depuis la plus grande route","Le véhicule à votre droite à chaque entrée"], e:"On cède le passage en entrant et on continue d'avancer une fois dans l'anneau, ce qui garde la circulation fluide." },
    c:0 },
  { id:"abs39", sec:"signs", sign:"warn-farm-machinery",
    en:{ q:"You see this sign on a rural road at harvest time. What should you be ready for?", a:["Loose livestock crossing between fields","Wide, slow equipment that may take up part of your lane","A weigh scale that every vehicle must pull into","Grain trucks parked along both shoulders"], e:"Some machines are wider than the lane, so pass only when you can see far ahead and the operator can see you. 🚜" },
    fr:{ q:"Vous voyez ce panneau sur une route rurale pendant les récoltes. À quoi devez-vous vous attendre ?", a:["Du bétail qui traverse entre deux champs","De la machinerie large et lente qui peut occuper une partie de votre voie","Une balance où tous les véhicules doivent s'arrêter","Des camions à grain stationnés sur les deux accotements"], e:"Certaines machines sont plus larges que la voie, alors dépassez seulement si vous voyez loin devant et que le conducteur vous voit. 🚜" },
    c:1 },
  { id:"abs40", sec:"signs", sign:"warn-truck-crossing",
    en:{ q:"This sign stands beside a highway near a gravel pit. What does it warn you about?", a:["A weigh station that trucks are required to enter","A long hill that trucks climb very slowly","Heavy trucks turning on and off the highway here","A lane that is reserved for trucks only"], e:"A loaded truck pulling onto a highway needs a long time to reach traffic speed, so ease off early." },
    fr:{ q:"Ce panneau est installé au bord d'une route près d'une gravière. Contre quoi vous met-il en garde ?", a:["Un poste de pesée où les camions doivent entrer","Une longue côte que les camions montent très lentement","Des camions lourds qui entrent sur la route et en sortent ici","Une voie réservée aux camions seulement"], e:"Un camion chargé qui s'engage sur une route met longtemps à atteindre la vitesse de la circulation, alors levez le pied tôt." },
    c:2 },
  { id:"abs41", sec:"signs", sign:"warn-low-clearance",
    en:{ q:"You are driving a rented moving truck and this sign shows a height lower than your load. What must you do?", a:["Let some air out of the tires and drive through slowly","Drive through in the centre, where the arch is highest","Follow another truck through at the same speed","Turn around and take a route with more room"], e:"The number on the sign is the real limit, and drivers who guess end up wedged under the bridge." },
    fr:{ q:"Vous conduisez un camion de déménagement loué et ce panneau indique une hauteur plus basse que votre chargement. Que devez-vous faire ?", a:["Dégonfler un peu les pneus et passer lentement","Passer au centre, là où l'arche est la plus haute","Suivre un autre camion à la même vitesse","Faire demi-tour et prendre un chemin plus dégagé"], e:"Le chiffre du panneau est la vraie limite, et les conducteurs qui devinent finissent coincés sous le pont." },
    c:3 },
  { id:"abs42", sec:"signs", sign:"slow-vehicle",
    en:{ q:"You are travelling at highway speed and see this bright triangle on the back of a vehicle ahead. What does it tell you?", a:["That vehicle travels at forty kilometres per hour or less","That vehicle is carrying an oversized load","That vehicle is being towed and has no brakes","That vehicle is driven by a learner under supervision"], e:"The gap closes far faster than you expect, so ease off as soon as the orange triangle appears." },
    fr:{ q:"Vous roulez à la vitesse de l'autoroute et vous voyez ce triangle voyant à l'arrière d'un véhicule devant vous. Que vous indique-t-il ?", a:["Ce véhicule roule à quarante kilomètres à l'heure ou moins","Ce véhicule transporte une charge hors normes","Ce véhicule est remorqué et n'a pas de freins","Ce véhicule est conduit par un apprenti accompagné"], e:"La distance se referme bien plus vite qu'on le croit, alors levez le pied dès que le triangle orange apparaît." },
    c:0 },
  { id:"abs43", sec:"signs", sign:"warn-fallen-rock",
    en:{ q:"You see this sign on a mountain highway after heavy rain. What should you be watching for?", a:["Gravel trucks pulling out of a pit","Loose rock lying on the road around blind curves","A bridge deck that ices before the road does","A steep grade where trucks lose their speed"], e:"Rain loosens the slope above the road, so look far ahead and keep room to steer around anything on the pavement." },
    fr:{ q:"Vous voyez ce panneau sur une route de montagne après une forte pluie. À quoi devez-vous faire attention ?", a:["À des camions de gravier qui sortent d'une gravière","À des pierres tombées sur la route dans les courbes sans visibilité","À un tablier de pont qui gèle avant la route","À une forte pente où les camions perdent leur vitesse"], e:"La pluie fragilise la pente au-dessus de la route, alors regardez loin devant et gardez de l'espace pour contourner un obstacle." },
    c:1 },
  { id:"abs44", sec:"signs", sign:"warn-pavement-ends",
    en:{ q:"This sign appears on a rural highway. How should you change your driving?", a:["Move closer to the vehicle ahead to stay out of the dust","Hold your speed so the tires stay on top of the surface","Slow down, because grip and stopping distance both get worse","Drive down the centre of the road to avoid soft edges"], e:"Gravel gives far less grip than pavement, so a speed that felt fine a minute ago is no longer safe." },
    fr:{ q:"Ce panneau apparaît sur une route rurale. Comment devez-vous changer votre conduite ?", a:["Vous rapprocher du véhicule devant pour éviter la poussière","Garder votre vitesse pour que les pneus restent sur le dessus","Ralentir, car l'adhérence et la distance de freinage empirent","Rouler au centre de la route pour éviter les bords mous"], e:"Le gravier offre bien moins d'adhérence que l'asphalte, alors une vitesse correcte il y a une minute ne l'est plus." },
    c:2 },
  { id:"abs45", sec:"signs", sign:"hazard-marker",
    en:{ q:"This marker is fixed to a post at the edge of the road. What is it telling you?", a:["That the road is about to change to gravel","That a driveway joins the road at this point","That you have reached the end of a passing zone","That an obstacle is here, and which side to pass it on"], e:"The stripes slope down toward the side you should drive on, so follow the slope." },
    fr:{ q:"Ce repère est fixé à un poteau au bord de la route. Que vous indique-t-il ?", a:["Que la route va devenir une route de gravier","Qu'une entrée privée rejoint la route à cet endroit","Que vous arrivez à la fin d'une zone de dépassement","Qu'un obstacle se trouve ici, et de quel côté le contourner"], e:"Les bandes descendent vers le côté où vous devez passer, alors suivez la pente des bandes." },
    c:3 },
  { id:"abs46", sec:"signs", sign:"temp-construction",
    en:{ q:"You reach this sign at night and the work crew has gone home. Why should you still slow down?", a:["Because loose gravel, drop offs and open trenches are still there","Because equipment operators may be watching from a distance","Because the road is always narrower after dark","Because headlights make fresh pavement harder to see"], e:"A work zone is a changed road, and the hazards stay long after the crew has left. 🚧" },
    fr:{ q:"Vous arrivez à ce panneau la nuit et l'équipe de travail est partie. Pourquoi faut-il quand même ralentir ?", a:["Parce que le gravier, les dénivellations et les tranchées ouvertes sont toujours là","Parce que des opérateurs de machinerie vous observent peut-être de loin","Parce que la route est toujours plus étroite la nuit","Parce que les phares rendent l'asphalte neuf plus difficile à voir"], e:"Une zone de travaux est une route transformée, et les dangers restent bien après le départ de l'équipe. 🚧" },
    c:0 },
  { id:"abs47", sec:"signs", sign:"temp-flagger",
    en:{ q:"This sign warns that a person is controlling traffic ahead. Whose direction do you follow when you get there?", a:["The posted signs, because a person cannot overrule them","The traffic control person, even ahead of signs and signals","The driver in front of you, whatever they choose to do","Your own judgement, once the road ahead looks clear"], e:"A work zone changes hour by hour, so the person on the ground knows what the signs cannot show." },
    fr:{ q:"Ce panneau annonce qu'une personne dirige la circulation plus loin. Quelles directives devez-vous suivre sur place ?", a:["Celles des panneaux, car une personne ne peut pas les contredire","Celles du signaleur, même avant les panneaux et les feux","Celles du conducteur devant vous, quoi qu'il décide","Votre propre jugement, dès que la route semble libre"], e:"Une zone de travaux change d'heure en heure, alors la personne sur place sait ce que les panneaux ne peuvent pas montrer." },
    c:1 },
  { id:"abs48", sec:"signs", sign:"temp-detour",
    en:{ q:"This sign appears because the road you wanted is closed. What is the right thing to do?", a:["Drive around the barricades if the road looks open","Park and wait until the road reopens","Follow the marked route until it brings you back","Turn around and go back the way you came"], e:"A marked route is planned to carry the extra traffic, while a shortcut of your own often ends at another closure." },
    fr:{ q:"Ce panneau apparaît parce que la route que vous vouliez prendre est fermée. Quelle est la bonne chose à faire ?", a:["Contourner les barrières si la route semble ouverte","Vous stationner et attendre la réouverture de la route","Suivre le chemin indiqué jusqu'à ce qu'il vous ramène","Faire demi-tour et repartir par où vous êtes venu"], e:"Le chemin indiqué est prévu pour absorber la circulation, alors qu'un raccourci improvisé finit souvent devant une autre fermeture." },
    c:2 },
  { id:"abs49", sec:"signs", sign:"temp-lane-closed",
    en:{ q:"Traffic is heavy and this sign shows your lane closing well ahead. What is the best thing to do?", a:["Stop where you are and wait for someone to wave you in","Straddle both lanes so that nobody can pass you","Drive to the very front of the line and squeeze in","Signal early and move over while gaps are still easy"], e:"Merging early and smoothly keeps the whole line moving, which gets everybody through sooner." },
    fr:{ q:"La circulation est dense et ce panneau annonce la fermeture de votre voie plus loin. Quelle est la meilleure chose à faire ?", a:["Vous arrêter sur place et attendre que quelqu'un vous fasse signe","Rouler à cheval sur les deux voies pour que personne ne vous dépasse","Rouler jusqu'au bout de la file et vous faufiler","Signaler tôt et changer de voie pendant que les espaces sont faciles"], e:"S'insérer tôt et en douceur garde toute la file en mouvement, ce qui fait passer tout le monde plus vite." },
    c:3 },
  { id:"abs50", sec:"signs", sign:"light-red",
    en:{ q:"You are stopped at this light and want to turn right, and no sign forbids the turn. When may you go?", a:["After a full stop, once the way is clear of vehicles and people","Right away, because a right turn never needs a stop","Only once the light changes to green","After counting to three at the stop line"], e:"A right turn on red is allowed only after a complete stop, and anyone in the crosswalk still goes first." },
    fr:{ q:"Vous êtes arrêté à ce feu et vous voulez tourner à droite, et aucun panneau ne l'interdit. Quand pouvez-vous partir ?", a:["Après un arrêt complet, une fois la voie libre de véhicules et de personnes","Tout de suite, car un virage à droite n'exige jamais d'arrêt","Seulement quand le feu passe au vert","Après avoir compté jusqu'à trois à la ligne d'arrêt"], e:"Le virage à droite au feu rouge n'est permis qu'après un arrêt complet, et les personnes sur le passage passent avant vous." },
    c:0 },
  { id:"abs51", sec:"signs", sign:"light-amber",
    en:{ q:"This light appears when you are so close to the intersection that stopping would mean slamming on the brakes. What should you do?", a:["Brake hard anyway and stop wherever you end up","Carry on through the intersection with care","Stop inside the crosswalk and wait for the next green","Speed up so you are through before it turns red"], e:"The rule is to stop if you safely can, and when you cannot, clearing the intersection is the safer choice." },
    fr:{ q:"Ce feu apparaît alors que vous êtes si près de l'intersection qu'un arrêt exigerait un freinage brusque. Que devez-vous faire ?", a:["Freiner brusquement quand même et vous arrêter n'importe où","Poursuivre et franchir l'intersection avec prudence","Vous arrêter sur le passage pour piétons et attendre le prochain vert","Accélérer pour passer avant que le feu devienne rouge"], e:"La règle est de s'arrêter si on peut le faire en sécurité, et quand ce n'est pas possible, dégager l'intersection est plus sûr." },
    c:1 },
  { id:"abs52", sec:"signs", sign:"light-green",
    en:{ q:"This light is showing, but stopped traffic has the intersection completely blocked. What must you do?", a:["Enter and wait in the middle until space opens","Enter and use the crosswalk area to get through","Wait behind the line until there is room to clear it","Sound your horn until the vehicles ahead move"], e:"A green light means go only if you can get all the way through, because a blocked intersection stops everybody." },
    fr:{ q:"Ce feu est allumé, mais des véhicules immobilisés bloquent complètement l'intersection. Que devez-vous faire ?", a:["Entrer et attendre au milieu qu'une place se libère","Entrer et utiliser le passage pour piétons pour traverser","Attendre derrière la ligne jusqu'à ce qu'il y ait de la place","Klaxonner jusqu'à ce que les véhicules devant avancent"], e:"Un feu vert veut dire d'avancer seulement si vous pouvez traverser complètement, car une intersection bloquée arrête tout le monde." },
    c:2 },
  { id:"abs53", sec:"signs", sign:"light-green-arrow",
    en:{ q:"This arrow points left and lights up while the round light beside it is still red. What does that mean?", a:["You may turn left after giving way to oncoming traffic","You may go straight through the intersection","You must wait for the round light to turn green","You may turn left, because oncoming traffic is being held"], e:"A green arrow gives you a protected turn, though you still check the crosswalk before you move. ⬅️" },
    fr:{ q:"Cette flèche pointe vers la gauche et s'allume pendant que le feu rond à côté est encore rouge. Qu'est-ce que cela signifie ?", a:["Vous pouvez tourner à gauche après avoir cédé le passage aux véhicules en sens inverse","Vous pouvez traverser l'intersection tout droit","Vous devez attendre que le feu rond passe au vert","Vous pouvez tourner à gauche, car les véhicules en sens inverse sont retenus"], e:"La flèche verte vous donne un virage protégé, mais vous devez quand même vérifier le passage pour piétons avant d'avancer. ⬅️" },
    c:3 },
  { id:"abs54", sec:"signs", sign:"light-flashing-red",
    en:{ q:"You and a vehicle on your right reach this flashing light at the same moment. Who goes first?", a:["The vehicle on the right, after both of you have stopped","You, because you are on the through road","Whichever driver moves forward first","The larger of the two vehicles"], e:"A flashing red works exactly like a stop sign, and the usual right of way rules follow the stop." },
    fr:{ q:"Un véhicule à votre droite et vous arrivez en même temps à ce feu clignotant. Qui passe en premier ?", a:["Le véhicule de droite, une fois que vous vous êtes tous les deux arrêtés","Vous, parce que vous êtes sur la route principale","Le conducteur qui avance le premier","Le plus gros des deux véhicules"], e:"Un feu rouge clignotant fonctionne exactement comme un panneau d'arrêt, et les règles habituelles de priorité s'appliquent ensuite." },
    c:0 },
  { id:"abs55", sec:"signs", sign:"light-flashing-green",
    en:{ q:"In Alberta, what does this flashing light allow you to do?", a:["Proceed with caution, as you would at a yield sign","Turn left ahead of oncoming traffic, which is being held","Stop and then continue, as you would at a stop sign","Continue straight only, with no turns allowed"], e:"The flashing green gives your direction the intersection to itself, so a left turn is protected." },
    fr:{ q:"En Alberta, que vous permet de faire ce feu clignotant ?", a:["Avancer avec prudence, comme à un panneau de cession de passage","Tourner à gauche devant les véhicules en sens inverse, qui sont retenus","Vous arrêter puis repartir, comme à un panneau d'arrêt","Continuer tout droit seulement, sans aucun virage"], e:"Le vert clignotant réserve l'intersection à votre direction, alors le virage à gauche est protégé." },
    c:1 },
  { id:"abs56", sec:"signs", sign:"mark-solid-yellow",
    en:{ q:"A slow vehicle is ahead of you and the yellow line on your side is solid. What does that mean for you?", a:["You may pass if you finish before the line ends","You may pass if the oncoming lane looks empty","You must stay in your lane and wait","You may pass by using the shoulder on the right"], e:"A solid yellow line on your side means the view or the road ahead is not safe for passing here." },
    fr:{ q:"Un véhicule lent est devant vous et la ligne jaune de votre côté est continue. Qu'est-ce que cela signifie pour vous ?", a:["Vous pouvez dépasser si vous terminez avant la fin de la ligne","Vous pouvez dépasser si la voie inverse semble libre","Vous devez rester dans votre voie et attendre","Vous pouvez dépasser en utilisant l'accotement de droite"], e:"Une ligne jaune continue de votre côté signifie que la visibilité ou la route ne permet pas de dépasser ici." },
    c:2 },
  { id:"abs57", sec:"signs", sign:"mark-broken-yellow",
    en:{ q:"You want to pass a slow grain truck and the yellow line on your side is broken. What still has to be true?", a:["The truck must signal that it is safe to pass","You must be inside a town or village","You must complete the pass in under ten seconds","The oncoming lane must be clear far enough ahead"], e:"A broken line gives permission, not safety, because the judgement about the gap is still yours." },
    fr:{ q:"Vous voulez dépasser un camion à grain lent et la ligne jaune de votre côté est discontinue. Qu'est-ce qui doit quand même être vrai ?", a:["Le camion doit vous signaler qu'il est prudent de dépasser","Vous devez vous trouver dans une ville ou un village","Vous devez terminer le dépassement en moins de dix secondes","La voie inverse doit être libre sur une assez grande distance"], e:"Une ligne discontinue donne la permission, pas la sécurité, car le jugement sur l'espace reste le vôtre." },
    c:3 },
  { id:"abs58", sec:"signs", sign:"mark-white-lane",
    en:{ q:"You are on a city street with this marking between the lanes. What does the white colour tell you?", a:["Traffic in the next lane travels the same way you do","Traffic in the next lane comes toward you","The lane beside you is for buses only","The lane beside you ends a short way ahead"], e:"White separates lanes going the same direction, while yellow separates traffic going opposite ways." },
    fr:{ q:"Vous roulez dans une rue où ce marquage sépare les voies. Que vous indique la couleur blanche ?", a:["Les véhicules de la voie voisine roulent dans le même sens que vous","Les véhicules de la voie voisine viennent vers vous","La voie à côté de vous est réservée aux autobus","La voie à côté de vous se termine un peu plus loin"], e:"Le blanc sépare les voies qui vont dans le même sens, alors que le jaune sépare les sens opposés." },
    c:0 },
  { id:"abs59", sec:"signs", sign:"mark-stop-line",
    en:{ q:"You are stopping at this wide line painted across your lane. Where should the front of your vehicle end up?", a:["Level with the middle of the line","Just behind the line, without touching it","Past the line but before the crosswalk","Anywhere in the intersection with a clear view"], e:"The line is placed so that stopping behind it leaves the crosswalk and the cross traffic free." },
    fr:{ q:"Vous vous arrêtez à cette large ligne peinte en travers de votre voie. Où doit se trouver l'avant de votre véhicule ?", a:["Au milieu de la ligne","Juste derrière la ligne, sans la toucher","Après la ligne, mais avant le passage pour piétons","N'importe où dans l'intersection, avec une bonne vue"], e:"La ligne est placée pour qu'un arrêt derrière elle laisse le passage pour piétons et la circulation transversale libres." },
    c:1 },
  { id:"abs60", sec:"signs", sign:"mark-crosswalk",
    en:{ q:"A person is standing at the curb waiting to cross at these markings. What must you do?", a:["Continue, because they have not stepped onto the road","Sound your horn to let them know you are coming","Stop and let them cross before you go","Move into the far lane and drive past them"], e:"Someone waiting at the edge of a crosswalk has the right of way, and drivers behind you need to see you stop." },
    fr:{ q:"Une personne attend sur le trottoir pour traverser à ce marquage. Que devez-vous faire ?", a:["Continuer, car elle n'a pas encore mis le pied sur la chaussée","Klaxonner pour lui faire savoir que vous arrivez","Vous arrêter et la laisser traverser avant de repartir","Vous déplacer dans la voie éloignée et passer à côté d'elle"], e:"Une personne qui attend au bord d'un passage pour piétons a la priorité, et les conducteurs derrière vous doivent vous voir arrêter." },
    c:2 },
  { id:"abr1", sec:"rules", topic:"licensing",
    en:{ q:"What is the youngest age you can get a Class 7 learner's licence in Alberta?", a:["12","14","16","18"], e:"In Alberta you can apply for a Class 7 learner's licence at 14, and you need a parent's permission until you are 18." },
    fr:{ q:"Quel est l'âge minimum pour obtenir un permis d'apprenti de classe 7 en Alberta ?", a:["12","14","16","18"], e:"En Alberta, on peut demander un permis d'apprenti de classe 7 dès 14 ans, et il faut l'accord d'un parent jusqu'à 18 ans." },
    c:1 },
  { id:"abr2", sec:"rules", topic:"licensing",
    en:{ q:"How long must you hold a Class 7 learner's licence in Alberta before you can take the basic road test?", a:["3 months","6 months","12 months","24 months"], e:"In Alberta the learner stage lasts at least 12 months, which gives you a full year of practice in every season." },
    fr:{ q:"Combien de temps devez-vous détenir un permis d'apprenti de classe 7 en Alberta avant de passer l'examen routier de base ?", a:["3 mois","6 mois","12 mois","24 mois"], e:"En Alberta, l'étape d'apprenti dure au moins 12 mois, ce qui donne une année complète de pratique dans toutes les saisons." },
    c:2 },
  { id:"abr3", sec:"rules", topic:"licensing",
    en:{ q:"Who is allowed to sit beside you while you drive with an Alberta Class 7 learner's licence?", a:["A fully licensed Class 5 driver who is 18 or older","Any adult who has held a licence for one year","A Class 5-GDL driver who is 18 or older","Any passenger over the age of 16"], e:"In Alberta your supervisor must hold a full Class 5 licence, be at least 18, and sit in the front passenger seat. 🚗" },
    fr:{ q:"Qui peut s'asseoir à côté de vous quand vous conduisez avec un permis d'apprenti de classe 7 en Alberta ?", a:["Un conducteur titulaire d'un permis complet de classe 5 âgé de 18 ans ou plus","Tout adulte qui a un permis depuis un an","Un conducteur de classe 5-GDL âgé de 18 ans ou plus","Tout passager âgé de plus de 16 ans"], e:"En Alberta, votre accompagnateur doit détenir un permis complet de classe 5, avoir au moins 18 ans et s'asseoir sur le siège avant du passager. 🚗" },
    c:0 },
  { id:"abr4", sec:"rules", topic:"licensing",
    en:{ q:"During which hours may a Class 7 learner in Alberta not drive at all?", a:["10 p.m. to 4 a.m.","11 p.m. to 6 a.m.","1 a.m. to 6 a.m.","Midnight to 5 a.m."], e:"In Alberta a Class 7 learner must stay off the road between midnight and 5 a.m., even with a supervisor beside them." },
    fr:{ q:"Pendant quelles heures un apprenti de classe 7 en Alberta n'a-t-il pas le droit de conduire ?", a:["De 22 h à 4 h","De 23 h à 6 h","De 1 h à 6 h","De minuit à 5 h"], e:"En Alberta, un apprenti de classe 7 ne doit pas conduire entre minuit et 5 h, même avec un accompagnateur à ses côtés." },
    c:3 },
  { id:"abr5", sec:"rules", topic:"licensing",
    en:{ q:"What is the passenger rule for an Alberta learner or probationary driver?", a:["Only one passenger is allowed at any time","You may not carry more people than there are seat belts","No passengers under 16 years old are allowed","Passengers are allowed only during daylight hours"], e:"In Alberta a graduated licensing driver may carry passengers, but every person needs their own seat belt." },
    fr:{ q:"Quelle est la règle sur les passagers pour un apprenti ou un conducteur probatoire en Alberta ?", a:["Un seul passager est permis en tout temps","Vous ne pouvez pas transporter plus de personnes qu'il y a de ceintures","Aucun passager de moins de 16 ans n'est permis","Les passagers ne sont permis que pendant le jour"], e:"En Alberta, un conducteur du programme de permis graduel peut transporter des passagers, mais chaque personne a besoin de sa propre ceinture." },
    c:1 },
  { id:"abr6", sec:"rules", topic:"licensing",
    en:{ q:"How long does the Class 5-GDL probationary stage last in Alberta at a minimum?", a:["6 months","1 year","2 years","3 years"], e:"In Alberta you must spend at least two years as a Class 5-GDL driver before you can move up to a full licence." },
    fr:{ q:"Combien de temps dure au minimum l'étape probatoire de classe 5-GDL en Alberta ?", a:["6 mois","1 an","2 ans","3 ans"], e:"En Alberta, il faut passer au moins deux ans comme conducteur de classe 5-GDL avant de pouvoir obtenir un permis complet." },
    c:2 },
  { id:"abr7", sec:"rules", topic:"licensing",
    en:{ q:"Besides finishing the probationary time, what does Alberta ask of you before you can hold a full Class 5 licence?", a:["A refresher course at a driving school","A second written test on the rules of the road","A letter of support from a driving instructor","No suspensions or demerit points in the last year"], e:"In Alberta you must also be at least 18 and have kept a clean record for the final 12 months of the graduated licensing stage." },
    fr:{ q:"En plus de terminer la période probatoire, qu'exige l'Alberta avant de vous accorder un permis complet de classe 5 ?", a:["Un cours de perfectionnement dans une école de conduite","Un deuxième examen écrit sur le code de la route","Une lettre d'appui d'un moniteur de conduite","Aucune suspension ni point d'inaptitude durant la dernière année"], e:"En Alberta, vous devez aussi avoir au moins 18 ans et garder un dossier vierge pendant les 12 derniers mois de l'étape de permis graduel." },
    c:3 },
  { id:"abr8", sec:"rules", topic:"licensing",
    en:{ q:"May a Class 5-GDL driver in Alberta act as the supervising driver for a learner?", a:["No, the supervisor must hold a full licence","Yes, as long as they are over 18 years old","Yes, if the learner is a member of their family","Yes, but only during daylight hours"], e:"In Alberta only a fully licensed driver can supervise a learner, so a probationary driver cannot take that seat." },
    fr:{ q:"Un conducteur de classe 5-GDL en Alberta peut-il servir d'accompagnateur pour un apprenti ?", a:["Non, l'accompagnateur doit détenir un permis complet","Oui, du moment qu'il a plus de 18 ans","Oui, si l'apprenti est un membre de sa famille","Oui, mais seulement pendant le jour"], e:"En Alberta, seul un conducteur titulaire d'un permis complet peut accompagner un apprenti, donc un conducteur probatoire ne peut pas occuper ce siège." },
    c:0 },
  { id:"abr9", sec:"rules", topic:"licence",
    en:{ q:"How many demerit points will suspend the licence of an Alberta graduated licensing driver?", a:["6","8","10","15"], e:"In Alberta a learner or probationary driver is suspended at 8 demerit points, while a fully licensed driver has more room." },
    fr:{ q:"Combien de points d'inaptitude entraînent la suspension du permis d'un conducteur albertain au permis graduel ?", a:["6","8","10","15"], e:"En Alberta, un apprenti ou un conducteur probatoire est suspendu à 8 points d'inaptitude, alors qu'un conducteur au permis complet a plus de marge." },
    c:1 },
  { id:"abr10", sec:"rules", topic:"licence",
    en:{ q:"A driver with a full Alberta licence is suspended once they reach how many demerit points?", a:["8","9","12","15"], e:"In Alberta a fully licensed driver is suspended at 15 demerit points collected within two years." },
    fr:{ q:"Un conducteur titulaire d'un permis albertain complet est suspendu lorsqu'il atteint combien de points d'inaptitude ?", a:["8","9","12","15"], e:"En Alberta, un conducteur au permis complet est suspendu à 15 points d'inaptitude accumulés en deux ans." },
    c:3 },
  { id:"abr11", sec:"rules", topic:"licence",
    en:{ q:"How long do demerit points stay on an Alberta driving record?", a:["6 months from the date of the offence","1 year from the date of conviction","2 years from the date of conviction","5 years from the date of conviction"], e:"In Alberta demerit points drop off your record two years after the conviction date, though the conviction itself stays longer." },
    fr:{ q:"Combien de temps les points d'inaptitude restent-ils au dossier de conduite en Alberta ?", a:["6 mois à partir de la date de l'infraction","1 an à partir de la date de la déclaration de culpabilité","2 ans à partir de la date de la déclaration de culpabilité","5 ans à partir de la date de la déclaration de culpabilité"], e:"En Alberta, les points d'inaptitude disparaissent du dossier deux ans après la déclaration de culpabilité, même si la condamnation y reste plus longtemps." },
    c:2 },
  { id:"abr12", sec:"rules", topic:"licence",
    en:{ q:"How long is a first demerit point suspension in Alberta?", a:["1 month","3 months","6 months","12 months"], e:"In Alberta a first demerit suspension lasts one month, and any later ones get longer." },
    fr:{ q:"Combien de temps dure une première suspension pour points d'inaptitude en Alberta ?", a:["1 mois","3 mois","6 mois","12 mois"], e:"En Alberta, une première suspension pour points dure un mois, et les suivantes sont plus longues." },
    c:0 },
  { id:"abr13", sec:"rules", topic:"licence",
    en:{ q:"A driver reaches the demerit limit again within a year of a first suspension. How long is the second suspension in Alberta?", a:["1 month","3 months","6 months","9 months"], e:"In Alberta the second suspension is three months and a third one is six months, so points add up faster than most people expect." },
    fr:{ q:"Un conducteur atteint de nouveau la limite de points dans l'année suivant une première suspension. Combien de temps dure la deuxième suspension en Alberta ?", a:["1 mois","3 mois","6 mois","9 mois"], e:"En Alberta, la deuxième suspension dure trois mois et la troisième, six mois : les points s'accumulent plus vite qu'on le croit." },
    c:1 },
  { id:"abr14", sec:"rules", topic:"licence",
    en:{ q:"An Alberta probationary driver gets their licence back after a demerit suspension. How many demerit points sit on their record then?", a:["0","2","3","7"], e:"In Alberta a graduated licensing driver restarts with 3 demerit points after a suspension, while a fully licensed driver restarts with 7." },
    fr:{ q:"Un conducteur probatoire de l'Alberta récupère son permis après une suspension pour points. Combien de points d'inaptitude figurent alors à son dossier ?", a:["0","2","3","7"], e:"En Alberta, un conducteur au permis graduel recommence avec 3 points d'inaptitude après une suspension, tandis qu'un conducteur au permis complet recommence avec 7." },
    c:2 },
  { id:"abr15", sec:"rules", topic:"licence",
    en:{ q:"How many demerit points come with a distracted driving conviction in Alberta?", a:["0","1","2","3"], e:"In Alberta distracted driving costs 3 demerit points plus a fine, which is already more than a third of the way to a probationary suspension. 📵" },
    fr:{ q:"Combien de points d'inaptitude entraîne une condamnation pour conduite distraite en Alberta ?", a:["0","1","2","3"], e:"En Alberta, la conduite distraite coûte 3 points d'inaptitude en plus d'une amende, soit déjà plus du tiers du chemin vers une suspension probatoire. 📵" },
    c:3 },
  { id:"abr16", sec:"rules", topic:"licence",
    en:{ q:"How many demerit points does an Alberta driver get for passing a school bus that has its red lights flashing?", a:["6","4","3","2"], e:"In Alberta this carries one of the heaviest point penalties, because children may be crossing the road right at that spot. 🚌" },
    fr:{ q:"Combien de points d'inaptitude un conducteur albertain reçoit-il pour avoir dépassé un autobus scolaire dont les feux rouges clignotent ?", a:["6","4","3","2"], e:"En Alberta, c'est une des sanctions les plus lourdes en points, car des enfants peuvent traverser la route juste à cet endroit. 🚌" },
    c:0 },
  { id:"abr17", sec:"rules", topic:"safe",
    en:{ q:"There is no speed limit sign on a street inside an Alberta city or town. What is the maximum speed?", a:["40 km/h","50 km/h","60 km/h","80 km/h"], e:"In Alberta the default limit inside an urban area is 50 km/h unless a sign shows something different." },
    fr:{ q:"Aucun panneau de limite de vitesse n'est affiché dans une rue d'une ville albertaine. Quelle est la vitesse maximale ?", a:["40 km/h","50 km/h","60 km/h","80 km/h"], e:"En Alberta, la limite par défaut dans une zone urbaine est de 50 km/h, sauf indication contraire d'un panneau." },
    c:1 },
  { id:"abr18", sec:"rules", topic:"safe",
    en:{ q:"Which default maximum speed applies on an Alberta roadway located outside an urban area?", a:["50 km/h","60 km/h","70 km/h","80 km/h"], e:"In Alberta the default limit outside an urban area is 80 km/h, so a faster highway always has posted signs." },
    fr:{ q:"Quelle vitesse maximale par défaut s'applique sur une route albertaine située à l'extérieur d'une zone urbaine ?", a:["50 km/h","60 km/h","70 km/h","80 km/h"], e:"En Alberta, la limite par défaut à l'extérieur d'une zone urbaine est de 80 km/h ; une route plus rapide est donc toujours indiquée par des panneaux." },
    c:3 },
  { id:"abr19", sec:"rules", topic:"safe",
    en:{ q:"What is the speed limit in an Alberta playground zone unless a sign shows something else?", a:["30 km/h","40 km/h","50 km/h","20 km/h"], e:"In Alberta both playground zones and school zones are 30 km/h unless another speed is posted. 🛝" },
    fr:{ q:"Quelle est la limite de vitesse dans une zone de terrain de jeu en Alberta, sauf indication contraire d'un panneau ?", a:["30 km/h","40 km/h","50 km/h","20 km/h"], e:"En Alberta, les zones de terrain de jeu et les zones scolaires sont à 30 km/h, sauf si une autre vitesse est affichée. 🛝" },
    c:0 },
  { id:"abr20", sec:"rules", topic:"safe",
    en:{ q:"When is the speed limit of an Alberta playground zone in effect?", a:["Only on weekends and holidays","Only during class hours on school days","Every day from 8:30 a.m. until one hour after sunset","Every day from sunrise until sunset"], e:"In Alberta playground zones apply every day of the year, weekends included, from 8:30 a.m. until one hour after sunset." },
    fr:{ q:"Quand la limite de vitesse d'une zone de terrain de jeu s'applique-t-elle en Alberta ?", a:["Seulement les fins de semaine et les jours fériés","Seulement pendant les heures de classe les jours d'école","Tous les jours, de 8 h 30 jusqu'à une heure après le coucher du soleil","Tous les jours, du lever au coucher du soleil"], e:"En Alberta, les zones de terrain de jeu s'appliquent tous les jours de l'année, fins de semaine comprises, de 8 h 30 jusqu'à une heure après le coucher du soleil." },
    c:2 },
  { id:"abr21", sec:"rules", topic:"safe",
    en:{ q:"When does the speed limit of an Alberta school zone normally apply?", a:["Every day of the year, from morning until night","On school days only, during set morning, lunch and afternoon periods","Between 8 a.m. and 4 p.m. every day of the week","Only while a crossing guard is standing at the corner"], e:"In Alberta school zones cover the busy arrival, lunch and dismissal periods on school days, and a municipality may post different hours." },
    fr:{ q:"Quand la limite de vitesse d'une zone scolaire s'applique-t-elle normalement en Alberta ?", a:["Tous les jours de l'année, du matin au soir","Seulement les jours d'école, pendant des périodes fixes le matin, le midi et l'après-midi","Entre 8 h et 16 h tous les jours de la semaine","Seulement lorsqu'un brigadier se tient au coin de la rue"], e:"En Alberta, les zones scolaires couvrent les périodes chargées d'arrivée, du dîner et de sortie des jours d'école, et une municipalité peut afficher des heures différentes." },
    c:1 },
  { id:"abr22", sec:"rules", topic:"safe",
    en:{ q:"May you pass another vehicle going the same way inside an Alberta school zone while the zone is in effect?", a:["Yes, as long as you stay under 30 km/h","Yes, if the other vehicle has stopped","Yes, if there are two lanes in each direction","No, passing is not allowed there"], e:"In Alberta passing is banned in school and playground zones while they are in effect, because a child can step out from between vehicles." },
    fr:{ q:"Pouvez-vous dépasser un autre véhicule circulant dans le même sens dans une zone scolaire albertaine pendant qu'elle est en vigueur ?", a:["Oui, du moment que vous restez sous 30 km/h","Oui, si l'autre véhicule est arrêté","Oui, s'il y a deux voies dans chaque direction","Non, le dépassement y est interdit"], e:"En Alberta, le dépassement est interdit dans les zones scolaires et de terrain de jeu pendant qu'elles sont en vigueur, car un enfant peut surgir entre deux véhicules." },
    c:3 },
  { id:"abr23", sec:"rules", topic:"safe",
    en:{ q:"In Alberta, what is the difference between a playground zone and a playground area?", a:["An area is in effect only on weekends","A zone applies to trucks and an area to all vehicles","A zone has a speed limit sign, while an area is only a warning","There is no real difference between the two words"], e:"In Alberta a zone sign sets a speed you must obey, while an area sign only warns you that children may be nearby." },
    fr:{ q:"En Alberta, quelle est la différence entre une zone de terrain de jeu et un secteur de terrain de jeu ?", a:["Un secteur est en vigueur seulement les fins de semaine","Une zone vise les camions et un secteur vise tous les véhicules","Une zone a un panneau de limite de vitesse, tandis qu'un secteur n'est qu'un avertissement","Il n'y a pas de vraie différence entre les deux mots"], e:"En Alberta, le panneau de zone impose une vitesse à respecter, tandis que le panneau de secteur vous avertit seulement que des enfants peuvent être à proximité." },
    c:2 },
  { id:"abr24", sec:"rules", topic:"safe",
    en:{ q:"Two vehicles arrive together at an Alberta intersection that has no signs and no lights. Who has the right of way?", a:["The vehicle on the right","The vehicle on the left","The larger of the two vehicles","The vehicle that is going straight through"], e:"In Alberta you yield to the vehicle on your right at an uncontrolled intersection, but always make eye contact and be ready to wait." },
    fr:{ q:"Deux véhicules arrivent en même temps à une intersection albertaine sans panneaux ni feux. Qui a la priorité ?", a:["Le véhicule à droite","Le véhicule à gauche","Le plus gros des deux véhicules","Le véhicule qui va tout droit"], e:"En Alberta, on cède le passage au véhicule à sa droite à une intersection sans contrôle, mais établissez un contact visuel et soyez prêt à attendre." },
    c:0 },
  { id:"abr25", sec:"rules", topic:"sharing",
    en:{ q:"In Alberta, which drivers must stop when a school bus turns on its alternately flashing red lights?", a:["Only drivers who are following the bus","Drivers following the bus and drivers coming the other way","Only drivers in the lane beside the bus","Only drivers who can see children on the road"], e:"In Alberta traffic in both directions must stop for flashing red school bus lights, unless a median separates the two sides." },
    fr:{ q:"En Alberta, quels conducteurs doivent s'arrêter lorsqu'un autobus scolaire allume ses feux rouges clignotants alternés ?", a:["Seulement les conducteurs qui suivent l'autobus","Les conducteurs qui suivent l'autobus et ceux qui viennent en sens inverse","Seulement les conducteurs dans la voie à côté de l'autobus","Seulement les conducteurs qui voient des enfants sur la route"], e:"En Alberta, la circulation dans les deux sens doit s'arrêter devant des feux rouges clignotants d'autobus scolaire, sauf si un terre-plein sépare les deux côtés." },
    c:1 },
  { id:"abr26", sec:"rules", topic:"sharing",
    en:{ q:"What do the flashing amber lights on an Alberta school bus tell you?", a:["The bus has finished picking up children","The bus driver is inviting you to pass","The bus is slowing down to stop","The bus has broken down"], e:"In Alberta amber lights are the warning stage, so the bus is about to stop and the red lights are coming next." },
    fr:{ q:"Que vous indiquent les feux ambre clignotants d'un autobus scolaire en Alberta ?", a:["L'autobus a fini de faire monter les enfants","Le conducteur vous invite à dépasser","L'autobus ralentit pour s'arrêter","L'autobus est tombé en panne"], e:"En Alberta, les feux ambre sont l'étape d'avertissement : l'autobus va s'arrêter et les feux rouges suivront." },
    c:2 },
  { id:"abr27", sec:"rules", topic:"sharing",
    en:{ q:"You have just passed a large truck and want to move back into its lane. When is it safe to pull in?", a:["As soon as your rear bumper clears the truck's front bumper","As soon as you can no longer hear the truck's engine","After counting two seconds from the start of the pass","When you can see the whole front of the truck in your mirror"], e:"Big vehicles need a long distance to stop, so give the truck back all the space it needs before you pull in. 🚛" },
    fr:{ q:"Vous venez de dépasser un gros camion et vous voulez revenir dans sa voie. Quand est-il sécuritaire de vous rabattre ?", a:["Dès que votre pare-chocs arrière dépasse l'avant du camion","Dès que vous n'entendez plus le moteur du camion","Après avoir compté deux secondes depuis le début du dépassement","Quand vous voyez tout l'avant du camion dans votre rétroviseur"], e:"Les gros véhicules ont besoin d'une longue distance pour freiner, alors redonnez au camion tout l'espace dont il a besoin avant de vous rabattre. 🚛" },
    c:3 },
  { id:"abr28", sec:"rules", topic:"sharing",
    en:{ q:"A large truck ahead of you signals a right turn but first swings out to the left. What is going on?", a:["The truck needs extra room to make the right turn","The truck driver has changed their mind about turning","The truck is pulling over to let you go by","The truck's signal light is broken"], e:"Long vehicles often need more than one lane to turn, so never try to squeeze up the right side of a turning truck." },
    fr:{ q:"Un gros camion devant vous signale un virage à droite, mais se déporte d'abord vers la gauche. Que se passe-t-il ?", a:["Le camion a besoin de plus d'espace pour tourner à droite","Le conducteur a changé d'idée au sujet du virage","Le camion se range pour vous laisser passer","Le clignotant du camion est défectueux"], e:"Les longs véhicules ont souvent besoin de plus d'une voie pour tourner, alors ne tentez jamais de vous faufiler à la droite d'un camion qui tourne." },
    c:0 },
  { id:"abr29", sec:"rules", topic:"sharing",
    en:{ q:"What does an orange triangle with a red border on the back of a vehicle mean?", a:["The vehicle is carrying dangerous goods","The vehicle travels slowly","The vehicle is driven by a student driver","The vehicle is towing a trailer"], e:"That sign marks a slow moving vehicle such as farm equipment, and you will close the gap on it very quickly. 🚜" },
    fr:{ q:"Que signifie un triangle orange bordé de rouge à l'arrière d'un véhicule ?", a:["Le véhicule transporte des marchandises dangereuses","Le véhicule roule lentement","Le véhicule est conduit par un apprenti","Le véhicule tire une remorque"], e:"Ce panneau signale un véhicule lent, comme de la machinerie agricole, et vous vous en approcherez très vite. 🚜" },
    c:1 },
  { id:"abr30", sec:"rules", topic:"sharing",
    en:{ q:"You come up behind a slow moving farm vehicle on an Alberta highway. What is the best thing to do?", a:["Sound your horn until the driver pulls over","Follow closely so you are ready to pass","Stay back and pass only when it is clearly safe","Go by on the right shoulder to get past quickly"], e:"Slow moving vehicle drivers are expected to pull over when they safely can, so a little patience costs you very little time." },
    fr:{ q:"Vous arrivez derrière un véhicule agricole lent sur une route albertaine. Quelle est la meilleure chose à faire ?", a:["Klaxonner jusqu'à ce que le conducteur se range","Le suivre de près pour être prêt à dépasser","Rester loin derrière et ne dépasser que si c'est clairement sécuritaire","Passer par l'accotement de droite pour vous dégager vite"], e:"Les conducteurs de véhicules lents doivent se ranger dès qu'ils le peuvent en sécurité, alors un peu de patience vous coûte très peu de temps." },
    c:2 },
  { id:"abr31", sec:"rules", topic:"sharing",
    en:{ q:"Why should you check your blind spots before every lane change, even on a quiet road?", a:["A motorcycle or bicycle can hide completely in a blind spot","Mirrors stop working properly at low speeds","The law asks for a shoulder check only inside cities","Blind spots exist only on the passenger side"], e:"Mirrors miss a slice of road beside you and a narrow vehicle fits inside it perfectly, so a quick shoulder check finds it." },
    fr:{ q:"Pourquoi faut-il vérifier vos angles morts avant chaque changement de voie, même sur une route tranquille ?", a:["Une moto ou un vélo peut disparaître complètement dans un angle mort","Les rétroviseurs cessent de bien fonctionner à basse vitesse","La loi n'exige un coup d'oeil par-dessus l'épaule qu'en ville","Les angles morts n'existent que du côté passager"], e:"Les rétroviseurs laissent une bande de route invisible à côté de vous et un véhicule étroit y tient parfaitement, alors un coup d'oeil par-dessus l'épaule le révèle." },
    c:0 },
  { id:"abr32", sec:"rules", topic:"conditions",
    en:{ q:"A tow truck is stopped on the shoulder of an Alberta highway with its lights flashing. What speed must you slow to as you go past?", a:["30 km/h, or the posted limit if it is lower","50 km/h, or the posted limit if it is lower","60 km/h, or the posted limit if it is lower","70 km/h, or the posted limit if it is lower"], e:"In Alberta you must slow to 60 km/h, or to the posted limit when that is lower, for any stopped vehicle with flashing lights." },
    fr:{ q:"Une dépanneuse est arrêtée sur l'accotement d'une route albertaine, gyrophares allumés. À quelle vitesse devez-vous ralentir pour la dépasser ?", a:["30 km/h, ou la limite affichée si elle est plus basse","50 km/h, ou la limite affichée si elle est plus basse","60 km/h, ou la limite affichée si elle est plus basse","70 km/h, ou la limite affichée si elle est plus basse"], e:"En Alberta, vous devez ralentir à 60 km/h, ou à la limite affichée si elle est plus basse, devant tout véhicule arrêté aux gyrophares allumés." },
    c:2 },
  { id:"abr33", sec:"rules", topic:"conditions",
    en:{ q:"Which stopped vehicles does Alberta's slow down and move over rule protect?", a:["Police cars and ambulances only","Police, ambulances, fire trucks, tow trucks and maintenance trucks","Any vehicle at all that is stopped on the shoulder","Only vehicles inside a marked construction zone"], e:"In Alberta the rule covers every roadside worker with flashing lights, including tow truck operators and highway maintenance crews." },
    fr:{ q:"Quels véhicules arrêtés la règle albertaine de ralentir et de changer de voie protège-t-elle ?", a:["Seulement les voitures de police et les ambulances","La police, les ambulances, les camions de pompiers, les dépanneuses et les camions d'entretien","N'importe quel véhicule arrêté sur l'accotement","Seulement les véhicules dans une zone de travaux balisée"], e:"En Alberta, la règle protège tout travailleur routier aux gyrophares allumés, y compris les dépanneurs et les équipes d'entretien des routes." },
    c:1 },
  { id:"abr34", sec:"rules", topic:"conditions",
    en:{ q:"A highway maintenance truck is working ahead of you with its lights flashing, and there are two lanes in your direction. Besides slowing down, what does Alberta ask of you?", a:["Turn on your four-way flashers","Sound your horn once as a warning","Come to a complete stop before going past","Move into the far lane if you can do it safely"], e:"In Alberta you must give roadside workers an empty lane when there is one, and slow right down when moving over is not safe." },
    fr:{ q:"Un camion d'entretien routier travaille devant vous, gyrophares allumés, et il y a deux voies dans votre direction. En plus de ralentir, qu'exige l'Alberta de vous ?", a:["Allumer vos feux de détresse","Klaxonner une fois en guise d'avertissement","Faire un arrêt complet avant de passer","Vous déplacer dans la voie éloignée si c'est sécuritaire"], e:"En Alberta, vous devez laisser une voie libre aux travailleurs routiers quand c'est possible, et bien ralentir lorsque le changement de voie n'est pas sécuritaire." },
    c:3 },
  { id:"abr35", sec:"rules", topic:"conditions",
    en:{ q:"What happens to a speeding fine in Alberta when roadside workers are present?", a:["The fine is doubled","The fine stays exactly the same","The fine becomes a simple warning","The fine is replaced by demerit points"], e:"In Alberta speeding fines double where workers are on the road, because a small mistake can hurt someone standing a few metres away." },
    fr:{ q:"Qu'arrive-t-il à une amende pour excès de vitesse en Alberta lorsque des travailleurs routiers sont présents ?", a:["L'amende est doublée","L'amende reste exactement la même","L'amende devient un simple avertissement","L'amende est remplacée par des points d'inaptitude"], e:"En Alberta, les amendes pour excès de vitesse doublent là où des travailleurs sont sur la route, car une petite erreur peut blesser quelqu'un à quelques mètres." },
    c:0 },
  { id:"abr36", sec:"rules", topic:"conditions",
    en:{ q:"On wet or slippery roads, how much following distance does Alberta advise?", a:["The same as on a dry road","About one and a half times the normal distance","At least three times the normal distance","Exactly twice the normal distance"], e:"In Alberta the winter advice is to leave at least three times your usual gap, because stopping on ice takes far longer." },
    fr:{ q:"Sur une chaussée mouillée ou glissante, quelle distance de suivi l'Alberta conseille-t-elle ?", a:["La même que sur une chaussée sèche","Environ une fois et demie la distance normale","Au moins trois fois la distance normale","Exactement le double de la distance normale"], e:"En Alberta, le conseil hivernal est de garder au moins trois fois votre écart habituel, car s'arrêter sur la glace prend beaucoup plus de temps." },
    c:2 },
  { id:"abr37", sec:"rules", topic:"conditions",
    en:{ q:"Before driving away on a snowy Alberta morning, what should you clear off your vehicle?", a:["Only the front windshield","Windows, mirrors, headlights, tail lights and the licence plate","Only the windows and the roof","Only the windows and the hood"], e:"In Alberta you need to see out and to be seen, so snow comes off the glass, the mirrors, every light and the plate. ❄️" },
    fr:{ q:"Avant de partir par un matin enneigé en Alberta, que devez-vous déneiger sur votre véhicule ?", a:["Seulement le pare-brise avant","Les vitres, les rétroviseurs, les phares, les feux arrière et la plaque","Seulement les vitres et le toit","Seulement les vitres et le capot"], e:"En Alberta, il faut voir et être vu, alors la neige s'enlève des vitres, des rétroviseurs, de tous les feux et de la plaque. ❄️" },
    c:1 },
  { id:"abr38", sec:"rules", topic:"conditions",
    en:{ q:"You are behind a snowplow on an Alberta highway during a storm. What should you do?", a:["Pass on the right where the road looks clear","Drive close behind so you stay in its cleared track","Flash your lights so the operator lets you by","Stay well back and wait until the operator lets you pass"], e:"Snowplows throw up snow that blinds you, and the road ahead of the plow is always worse than the road behind it." },
    fr:{ q:"Vous suivez une déneigeuse sur une route albertaine pendant une tempête. Que devez-vous faire ?", a:["Dépasser par la droite là où la route semble dégagée","Rouler tout près derrière pour rester dans sa trace dégagée","Faire des appels de phares pour qu'on vous laisse passer","Rester bien derrière et attendre que l'opérateur vous laisse passer"], e:"Les déneigeuses projettent de la neige qui vous aveugle, et la route devant la déneigeuse est toujours pire que celle derrière elle." },
    c:3 },
  { id:"abr39", sec:"rules", topic:"impaired",
    en:{ q:"How much alcohol may an Alberta Class 7 or Class 5-GDL driver have in their body while driving?", a:["None at all","Less than 0.02","Less than 0.05","Less than 0.08"], e:"In Alberta every graduated licensing driver must be at zero for alcohol and drugs, no matter the time of day." },
    fr:{ q:"Quelle quantité d'alcool un conducteur albertain de classe 7 ou de classe 5-GDL peut-il avoir dans le corps au volant ?", a:["Aucune","Moins de 0,02","Moins de 0,05","Moins de 0,08"], e:"En Alberta, tout conducteur au permis graduel doit être à zéro pour l'alcool et les drogues, peu importe l'heure." },
    c:0 },
  { id:"abr40", sec:"rules", topic:"impaired",
    en:{ q:"An Alberta probationary driver is found with alcohol in their body. What is the immediate result?", a:["A warning letter and no suspension","A 30-day licence suspension and a 7-day vehicle seizure","A 3-day licence suspension and no vehicle seizure","A fine only, with no effect on the licence"], e:"In Alberta the zero tolerance penalty is handed out at the roadside, long before any court date arrives." },
    fr:{ q:"Un conducteur probatoire de l'Alberta est trouvé avec de l'alcool dans le corps. Quelle est la conséquence immédiate ?", a:["Une lettre d'avertissement sans suspension","Une suspension de permis de 30 jours et une saisie du véhicule de 7 jours","Une suspension de permis de 3 jours sans saisie du véhicule","Une amende seulement, sans effet sur le permis"], e:"En Alberta, la sanction de tolérance zéro est imposée sur place, bien avant toute audience au tribunal." },
    c:1 },
  { id:"abr41", sec:"rules", topic:"impaired",
    en:{ q:"A fully licensed Alberta driver tests in the 0.05 to 0.079 range for the first time. What happens right away?", a:["Nothing until a court hears the case","A written warning is added to the record","A 3-day licence suspension and a 3-day vehicle seizure","A 30-day licence suspension and a 30-day vehicle seizure"], e:"In Alberta an immediate roadside sanction applies even below the criminal limit, and it gets much heavier if it happens again." },
    fr:{ q:"Un conducteur albertain au permis complet obtient un résultat entre 0,05 et 0,079 pour la première fois. Que se passe-t-il immédiatement ?", a:["Rien avant l'audience au tribunal","Un avertissement écrit est ajouté au dossier","Une suspension de permis de 3 jours et une saisie du véhicule de 3 jours","Une suspension de permis de 30 jours et une saisie du véhicule de 30 jours"], e:"En Alberta, une sanction immédiate au bord de la route s'applique même sous la limite criminelle, et elle s'alourdit beaucoup en cas de récidive." },
    c:2 },
  { id:"abr42", sec:"rules", topic:"impaired",
    en:{ q:"Besides alcohol and illegal drugs, what else can bring an immediate roadside sanction in Alberta?", a:["Driving with an untidy vehicle","Driving with the radio turned up loud","Driving without a spare tire in the trunk","Driving while very tired or affected by prescription medicine"], e:"In Alberta the law looks at whether you are able to drive safely, not only at what caused the problem. 😴" },
    fr:{ q:"En plus de l'alcool et des drogues illégales, qu'est-ce qui peut entraîner une sanction immédiate au bord de la route en Alberta ?", a:["Conduire avec un véhicule en désordre","Conduire avec la radio à plein volume","Conduire sans pneu de secours dans le coffre","Conduire en étant très fatigué ou affecté par un médicament d'ordonnance"], e:"En Alberta, la loi regarde si vous êtes en mesure de conduire de façon sécuritaire, pas seulement la cause du problème. 😴" },
    c:3 },
  { id:"abr43", sec:"rules", topic:"impaired",
    en:{ q:"What is the penalty for a distracted driving conviction in Alberta?", a:["A $390 fine and 3 demerit points","A $200 fine and 2 demerit points","A $500 fine and no demerit points","A written warning for a first offence"], e:"In Alberta the ticket costs both money and points, and for a probationary driver those points matter even more. 📱" },
    fr:{ q:"Quelle est la sanction pour une condamnation pour conduite distraite en Alberta ?", a:["Une amende de 390 $ et 3 points d'inaptitude","Une amende de 200 $ et 2 points d'inaptitude","Une amende de 500 $ et aucun point d'inaptitude","Un avertissement écrit pour une première infraction"], e:"En Alberta, la contravention coûte à la fois de l'argent et des points, et pour un conducteur probatoire ces points comptent encore plus. 📱" },
    c:0 },
  { id:"abr44", sec:"rules", topic:"impaired",
    en:{ q:"You pick up your phone to read a message while stopped at a red light in Alberta. Is that allowed?", a:["Yes, because the vehicle is not moving","No, the law applies even when you are stopped at a light","Yes, if you put the phone down before the light turns green","Yes, if the message is only a few words long"], e:"In Alberta you are still driving when you are stopped in traffic, so a hand-held phone is still an offence." },
    fr:{ q:"Vous prenez votre téléphone pour lire un message pendant que vous êtes arrêté à un feu rouge en Alberta. Est-ce permis ?", a:["Oui, parce que le véhicule ne bouge pas","Non, la loi s'applique même à l'arrêt à un feu","Oui, si vous déposez le téléphone avant que le feu passe au vert","Oui, si le message ne fait que quelques mots"], e:"En Alberta, vous conduisez toujours lorsque vous êtes arrêté dans la circulation, donc un téléphone tenu à la main reste une infraction." },
    c:1 },
  { id:"abr45", sec:"rules", topic:"impaired",
    en:{ q:"Which of these is still allowed under Alberta's distracted driving law?", a:["Reading a paper map spread over the wheel","Putting on makeup while waiting at a red light","Talking on a hands-free phone","Typing an address into a device as you drive"], e:"In Alberta hands-free calls, navigation set up before you leave, and eating are allowed, while reading, grooming and hand-held devices are not." },
    fr:{ q:"Laquelle de ces actions est encore permise selon la loi albertaine sur la conduite distraite ?", a:["Lire une carte papier étalée sur le volant","Se maquiller en attendant à un feu rouge","Parler au téléphone en mode mains libres","Taper une adresse dans un appareil en roulant"], e:"En Alberta, les appels mains libres, la navigation réglée avant le départ et le fait de manger sont permis, mais lire, se maquiller et tenir un appareil ne le sont pas." },
    c:2 },
  { id:"abr46", sec:"rules", topic:"vehicle",
    en:{ q:"Alberta's vehicle equipment rules call for working brakes, mirrors, a horn and which of these?", a:["A dashboard camera","A first aid kit","A spare set of wiper blades","A muffler"], e:"In Alberta a vehicle needs safe brakes, lamps, mirrors, a horn and a muffler before it may legally be driven." },
    fr:{ q:"Les règles albertaines sur l'équipement des véhicules exigent des freins, des rétroviseurs, un klaxon et lequel de ces éléments ?", a:["Une caméra de tableau de bord","Une trousse de premiers soins","Un jeu de balais d'essuie-glace de rechange","Un silencieux"], e:"En Alberta, un véhicule a besoin de freins sûrs, de feux, de rétroviseurs, d'un klaxon et d'un silencieux pour circuler légalement." },
    c:3 },
  { id:"abr47", sec:"rules", topic:"vehicle",
    en:{ q:"Which lights does Alberta require a passenger vehicle to keep in working order?", a:["Headlamps, tail lamps, brake lamps and signal lamps","Headlamps and fog lamps only","Headlamps, tail lamps and roof lamps","Brake lamps and interior lamps only"], e:"In Alberta each of these lamps sends a message to other drivers, so one burned-out bulb can cost you a ticket. 💡" },
    fr:{ q:"Quels feux l'Alberta exige-t-elle en bon état de marche sur une voiture de tourisme ?", a:["Les phares, les feux arrière, les feux de freinage et les clignotants","Les phares et les phares antibrouillard seulement","Les phares, les feux arrière et les feux de toit","Les feux de freinage et l'éclairage intérieur seulement"], e:"En Alberta, chacun de ces feux envoie un message aux autres conducteurs, alors une seule ampoule grillée peut vous coûter une contravention. 💡" },
    c:0 },
  { id:"abr48", sec:"rules", topic:"vehicle",
    en:{ q:"What does Alberta law say about the way a seat belt must be worn?", a:["It may rest loosely across the lap","It must be properly adjusted and securely fastened","It may be tucked behind the shoulder if it feels tight","It is only needed on roads faster than 60 km/h"], e:"In Alberta a belt only does its job when it is snug and buckled, so a loose or tucked-away belt is close to no belt at all." },
    fr:{ q:"Que dit la loi albertaine sur la façon de porter la ceinture de sécurité ?", a:["Elle peut reposer lâchement sur les cuisses","Elle doit être bien ajustée et solidement bouclée","Elle peut être glissée derrière l'épaule si elle serre trop","Elle n'est requise que sur les routes de plus de 60 km/h"], e:"En Alberta, une ceinture ne fait son travail que si elle est bien ajustée et bouclée, alors une ceinture lâche ou glissée derrière soi ne vaut presque rien." },
    c:1 },
  { id:"abr49", sec:"rules", topic:"vehicle",
    en:{ q:"In Alberta, which children must ride in a properly installed child safety seat?", a:["All children under the age of 10","All children shorter than 145 cm","Children under 6 years old who weigh 18 kg (40 lb) or less","Children under 8 years old, whatever their weight"], e:"In Alberta the child seat rule uses both age and weight, and safety experts advise keeping a seat as long as the child still fits it." },
    fr:{ q:"En Alberta, quels enfants doivent voyager dans un siège d'auto correctement installé ?", a:["Tous les enfants de moins de 10 ans","Tous les enfants de moins de 145 cm","Les enfants de moins de 6 ans qui pèsent 18 kg (40 lb) ou moins","Les enfants de moins de 8 ans, peu importe leur poids"], e:"En Alberta, la règle du siège d'auto tient compte de l'âge et du poids, et les spécialistes conseillent de garder le siège tant que l'enfant y entre encore." },
    c:2 },
  { id:"abr50", sec:"rules", topic:"vehicle",
    en:{ q:"Who is responsible for making sure a 10-year-old passenger is buckled up in Alberta?", a:["The child","The child's parent, even when not in the vehicle","The person sitting in the front seat","The driver of the vehicle"], e:"In Alberta the driver must make sure every passenger aged 6 to 15 is wearing a seat belt." },
    fr:{ q:"Qui doit s'assurer qu'un passager de 10 ans est attaché en Alberta ?", a:["L'enfant lui-même","Le parent de l'enfant, même s'il n'est pas dans le véhicule","La personne assise sur le siège avant","Le conducteur du véhicule"], e:"En Alberta, le conducteur doit s'assurer que chaque passager de 6 à 15 ans porte sa ceinture de sécurité." },
    c:3 },
  { id:"abr51", sec:"rules", topic:"vehicle",
    en:{ q:"You are getting your vehicle ready for an Alberta winter. Which check matters most for seeing the road?", a:["The wipers, the washer fluid and the defroster","The paint and the wheel covers","The radio antenna and the speakers","The trunk lock and the spare key"], e:"Slush freezes onto the glass in seconds, so wipers, cold-rated washer fluid and a working defroster are winter basics. ❄️" },
    fr:{ q:"Vous préparez votre véhicule pour l'hiver albertain. Quelle vérification compte le plus pour bien voir la route ?", a:["Les essuie-glaces, le lave-glace et le dégivreur","La peinture et les enjoliveurs","L'antenne de radio et les haut-parleurs","La serrure du coffre et la clé de rechange"], e:"La gadoue gèle sur la vitre en quelques secondes, alors les essuie-glaces, un lave-glace pour le froid et un dégivreur qui fonctionne sont essentiels l'hiver. ❄️" },
    c:0 },
  { id:"abr52", sec:"rules", topic:"vehicle",
    en:{ q:"Alberta suggests keeping a winter emergency kit in your vehicle. Which set of items belongs in it?", a:["Spare plates, touch-up paint and a map case","A blanket, a flashlight, booster cables, a shovel and sand or kitty litter","A cooler, folding chairs and a portable radio","A tire pump, a car cover and a windshield sunshade"], e:"In Alberta a storm can leave you stranded far from help, so pack warmth, light, grip for the tires and a way to dig out. 🧣" },
    fr:{ q:"L'Alberta recommande de garder une trousse d'urgence hivernale dans le véhicule. Quel ensemble d'articles y a sa place ?", a:["Des plaques de rechange, de la peinture de retouche et un porte-cartes","Une couverture, une lampe de poche, des câbles de démarrage, une pelle et du sable ou de la litière","Une glacière, des chaises pliantes et une radio portative","Une pompe à pneu, une housse d'auto et un pare-soleil"], e:"En Alberta, une tempête peut vous immobiliser loin de tout secours, alors emportez de la chaleur, de la lumière, de l'adhérence pour les pneus et de quoi vous dégager. 🧣" },
    c:1 },
  { id:"abr53", sec:"rules", topic:"collisions",
    en:{ q:"In Alberta, how much combined damage means a collision must be reported to police?", a:["$1,000 or more","$2,000 or more","$5,000 or more","$10,000 or more"], e:"In Alberta a collision with $5,000 or more of combined damage must be reported to police on a collision report form." },
    fr:{ q:"En Alberta, à partir de quel montant de dommages combinés une collision doit-elle être signalée à la police ?", a:["1 000 $ ou plus","2 000 $ ou plus","5 000 $ ou plus","10 000 $ ou plus"], e:"En Alberta, une collision causant 5 000 $ ou plus de dommages combinés doit être signalée à la police au moyen d'un rapport de collision." },
    c:2 },
  { id:"abr54", sec:"rules", topic:"collisions",
    en:{ q:"What is the very first thing an Alberta driver must do after being in a collision?", a:["Stop the vehicle","Take photographs of the damage","Call their insurance company","Move the other vehicle off the road"], e:"In Alberta leaving the scene is a serious offence, so stopping comes before anything else you might want to do." },
    fr:{ q:"Quelle est la toute première chose qu'un conducteur albertain doit faire après une collision ?", a:["Arrêter le véhicule","Prendre des photos des dommages","Appeler sa compagnie d'assurance","Déplacer l'autre véhicule hors de la route"], e:"En Alberta, quitter les lieux est une infraction grave, alors il faut s'arrêter avant toute autre chose." },
    c:0 },
  { id:"abr55", sec:"rules", topic:"collisions",
    en:{ q:"When should you call 911 after a collision in Alberta?", a:["Any time a bit of paint is scratched","When someone is seriously hurt or a driver seems impaired","Only when a vehicle has caught fire","Only when the other driver asks you to"], e:"In Alberta call 911 for injuries or a driver you think is impaired. Smaller collisions can be reported afterwards." },
    fr:{ q:"Quand devez-vous appeler le 911 après une collision en Alberta ?", a:["Chaque fois qu'un peu de peinture est égratignée","Quand une personne est gravement blessée ou qu'un conducteur semble avoir les facultés affaiblies","Seulement quand un véhicule a pris feu","Seulement quand l'autre conducteur vous le demande"], e:"En Alberta, appelez le 911 en cas de blessés ou si vous croyez qu'un conducteur a les facultés affaiblies. Les collisions mineures peuvent être signalées ensuite." },
    c:1 },
  { id:"abr56", sec:"rules", topic:"collisions",
    en:{ q:"After a minor collision in Alberta, what must you exchange with the other driver?", a:["Only your first name","Only your licence plate number","Only the name of your repair shop","Your contact details and your insurance information"], e:"In Alberta both drivers need each other's contact and insurance details so the claims can be settled later." },
    fr:{ q:"Après une collision mineure en Alberta, que devez-vous échanger avec l'autre conducteur ?", a:["Seulement votre prénom","Seulement votre numéro de plaque","Seulement le nom de votre garage","Vos coordonnées et vos renseignements d'assurance"], e:"En Alberta, les deux conducteurs ont besoin des coordonnées et des renseignements d'assurance de l'autre pour régler les réclamations plus tard." },
    c:3 },
  { id:"abr57", sec:"rules", topic:"collisions",
    en:{ q:"The other driver refuses to give you any information and drives off. What should you do?", a:["Write down the plate number and describe the vehicle and driver","Follow the vehicle until it stops somewhere","Let it go, since nothing can be done now","Wait a week and then call your insurer"], e:"Details you write down in the first few minutes are what let police and your insurer trace the other driver. 📝" },
    fr:{ q:"L'autre conducteur refuse de vous donner des renseignements et quitte les lieux. Que devez-vous faire ?", a:["Noter le numéro de plaque et décrire le véhicule et le conducteur","Suivre le véhicule jusqu'à ce qu'il s'arrête quelque part","Laisser tomber, puisqu'on ne peut plus rien faire","Attendre une semaine avant d'appeler votre assureur"], e:"Les détails que vous notez dans les premières minutes permettent à la police et à votre assureur de retrouver l'autre conducteur. 📝" },
    c:0 },
  { id:"abr58", sec:"rules", topic:"collisions",
    en:{ q:"Should you tell your insurance company about a collision even when you were not at fault?", a:["No, only the driver at fault reports it","Yes, report it promptly no matter who was at fault","No, unless somebody was injured","Yes, but only if the damage is over $10,000"], e:"Your insurer needs your side of the story early, and reporting protects you if the other driver tells it differently." },
    fr:{ q:"Devez-vous signaler une collision à votre assureur même si vous n'êtes pas responsable ?", a:["Non, seul le conducteur responsable la signale","Oui, signalez-la rapidement, peu importe qui est responsable","Non, sauf si une personne a été blessée","Oui, mais seulement si les dommages dépassent 10 000 $"], e:"Votre assureur a besoin de votre version dès le début, et le signalement vous protège si l'autre conducteur raconte les choses autrement." },
    c:1 },
  { id:"abr59", sec:"rules", topic:"collisions",
    en:{ q:"An ambulance with lights and siren catches up to you on an Alberta street. Where should you bring your vehicle?", a:["Into the middle of the road so it can pass on either side","Into the nearest driveway or parking lot","As close to the curb as you can, parallel to the road, and stop","Straight through the next intersection at the same speed"], e:"In Alberta you pull over parallel to the curb and stay stopped until you are sure no other emergency vehicle is coming. 🚑" },
    fr:{ q:"Une ambulance aux gyrophares et à la sirène vous rattrape dans une rue albertaine. Où devez-vous amener votre véhicule ?", a:["Au milieu de la route pour qu'elle passe d'un côté ou de l'autre","Dans la première entrée de cour ou le premier stationnement","Le plus près possible du trottoir, parallèle à la route, puis arrêter","Tout droit à travers la prochaine intersection à la même vitesse"], e:"En Alberta, on se range parallèlement au trottoir et on reste arrêté jusqu'à ce qu'on soit certain qu'aucun autre véhicule d'urgence n'arrive. 🚑" },
    c:2 },
  { id:"abr60", sec:"rules", topic:"collisions",
    en:{ q:"How far back must you stay from a moving emergency vehicle that has its lights or siren on in Alberta?", a:["30 m","60 m","100 m","150 m"], e:"In Alberta you may not drive within 150 m of an emergency vehicle on a call, which is about one and a half city blocks." },
    fr:{ q:"À quelle distance devez-vous rester d'un véhicule d'urgence en mouvement dont les gyrophares ou la sirène fonctionnent en Alberta ?", a:["30 m","60 m","100 m","150 m"], e:"En Alberta, il est interdit de circuler à moins de 150 m d'un véhicule d'urgence en intervention, soit environ un pâté de maisons et demi." },
    c:3 }
);
