/* ---------- signs ---------- */

{ id:"abs61", sec:"signs", sign:"no-bicycles",
  en:{ q:"Who may not use the road past this sign?",
       a:["Cyclists","Trucks","People on foot","Motorcycles"],
       e:"Bicycles are banned here, usually because the road is too fast or narrow to share safely. Watch for a marked alternative route." },
  fr:{ q:"Qui ne peut pas emprunter la route après ce panneau ?",
       a:["Les cyclistes","Les camions","Les piétons","Les motocyclettes"],
       e:"Les vélos sont interdits ici, généralement parce que la route est trop rapide ou trop étroite pour être partagée. Cherchez un itinéraire de rechange indiqué." },
  c:0 },

{ id:"abs62", sec:"signs", sign:"no-pedestrians",
  en:{ q:"What does this sign prohibit?",
       a:["Turning on this road","Walking on this road","Cycling on this road","Parking on this road"],
       e:"People on foot must find another route. These signs appear where there is no sidewalk and traffic moves quickly." },
  fr:{ q:"Qu'interdit ce panneau ?",
       a:["Tourner sur cette route","Marcher sur cette route","Circuler à vélo sur cette route","Stationner sur cette route"],
       e:"Les piétons doivent emprunter un autre chemin. Ces panneaux apparaissent là où il n'y a pas de trottoir et où la circulation est rapide." },
  c:1 },

{ id:"abs63", sec:"signs", sign:"info-parking",
  en:{ q:"What does this blue P sign mean?",
       a:["Police station ahead","Pay a toll here","Parking is allowed here","Parking is forbidden here"],
       e:"Blue is the colour for information. Always read the smaller sign below it for the hours, time limit and any permit needed." },
  fr:{ q:"Que signifie ce panneau bleu avec un P ?",
       a:["Poste de police devant","Payer un péage ici","Le stationnement est permis ici","Le stationnement est interdit ici"],
       e:"Le bleu est la couleur de l'information. Lisez toujours le petit panneau en dessous pour les heures, la durée et le permis éventuel." },
  c:2 },

{ id:"abs64", sec:"signs", sign:"info-food",
  en:{ q:"What is this sign pointing you toward?",
       a:["A hospital","A campground","A viewpoint","A place to eat"],
       e:"On the long straight drives across Alberta, planning a meal and rest stop is a real safety measure, not a luxury." },
  fr:{ q:"Vers quoi ce panneau vous dirige-t-il ?",
       a:["Un hôpital","Un terrain de camping","Un belvédère","Un endroit où manger"],
       e:"Sur les longues lignes droites de l'Alberta, prévoir un repas et une pause est une véritable mesure de sécurité, pas un luxe." },
  c:3 },

{ id:"abs65", sec:"signs", sign:"info-route-401",
  en:{ q:"What does a highway route marker tell you?",
       a:["Which numbered highway you are on","The speed limit","The distance to the border","The weight limit"],
       e:"Route markers keep you oriented. Alberta's main ones are Highway 2 between Calgary and Edmonton, and Highway 1, the Trans-Canada." },
  fr:{ q:"Que vous indique un marqueur de route ?",
       a:["Sur quelle route numérotée vous êtes","La limite de vitesse","La distance jusqu'à la frontière","La limite de poids"],
       e:"Les marqueurs vous aident à vous orienter. Les principaux en Alberta sont la route 2 entre Calgary et Edmonton, et la route 1, la Transcanadienne." },
  c:0 },

{ id:"abs66", sec:"signs", sign:"info-trans-canada",
  en:{ q:"Which highway does this maple-leaf marker identify?",
       a:["A city ring road","The Trans-Canada Highway","A provincial park road","A toll road"],
       e:"The Trans-Canada runs coast to coast. In Alberta it passes through Calgary and on into the Rockies at Banff." },
  fr:{ q:"Quelle route ce marqueur à la feuille d'érable identifie-t-il ?",
       a:["Un périphérique urbain","La route Transcanadienne","Une route de parc provincial","Une route à péage"],
       e:"La Transcanadienne traverse le pays d'un océan à l'autre. En Alberta, elle passe par Calgary puis entre dans les Rocheuses à Banff." },
  c:1 },

{ id:"abs67", sec:"signs", sign:"warn-winding",
  en:{ q:"What is ahead when you see this sign?",
       a:["A roundabout","A dead end","Several curves in a row","One gentle bend"],
       e:"Set your speed before the first curve. Braking in the middle of a bend unsettles the car when you need grip most." },
  fr:{ q:"Qu'y a-t-il devant lorsque vous voyez ce panneau ?",
       a:["Un carrefour giratoire","Un cul-de-sac","Plusieurs courbes de suite","Une seule courbe douce"],
       e:"Réglez votre vitesse avant la première courbe. Freiner au milieu d'un virage déstabilise la voiture au moment où l'adhérence compte le plus." },
  c:2 },

{ id:"abs68", sec:"signs", sign:"warn-bump",
  en:{ q:"Why slow down for this sign?",
       a:["The road is closed","There is a toll","A police check is ahead","A bump can throw the car off line and jolt your steering"],
       e:"Hitting a bump at speed unloads the tires for a moment, so you have less grip and less steering exactly when you need them." },
  fr:{ q:"Pourquoi ralentir à ce panneau ?",
       a:["La route est fermée","Il y a un péage","Un contrôle policier se trouve devant","Une bosse peut déporter la voiture et secouer la direction"],
       e:"Franchir une bosse à vitesse allège les pneus un instant : vous perdez de l'adhérence et de la direction précisément quand vous en avez besoin." },
  c:3 },

{ id:"abs69", sec:"signs", sign:"warn-divided-begins",
  en:{ q:"What starts just ahead of this sign?",
       a:["A median separating the two directions","A gravel road","A school zone","A toll section"],
       e:"From here the two directions are separated. Keep right, and remember a U-turn across a median is never allowed." },
  fr:{ q:"Qu'est-ce qui commence juste après ce panneau ?",
       a:["Un terre-plein séparant les deux sens","Un chemin de gravier","Une zone scolaire","Une section à péage"],
       e:"À partir d'ici, les deux sens sont séparés. Tenez votre droite, et rappelez-vous qu'un demi-tour à travers un terre-plein est toujours interdit." },
  c:0 },

{ id:"abs70", sec:"signs", sign:"warn-pedestrian",
  en:{ q:"What is this yellow diamond warning you about?",
       a:["A pedestrian mall","People crossing the road ahead","A bus stop","A hospital entrance"],
       e:"Cover the brake and scan both shoulders. A warning sign means the hazard is likely, not certain — stay ready either way." },
  fr:{ q:"De quoi ce losange jaune vous avertit-il ?",
       a:["Une rue piétonne","Des gens traversent la route plus loin","Un arrêt d'autobus","L'entrée d'un hôpital"],
       e:"Gardez le pied près du frein et surveillez les deux accotements. Un panneau d'avertissement signale un danger probable, pas certain : restez prêt." },
  c:1 },

{ id:"abs71", sec:"signs", sign:"warn-school-bus",
  en:{ q:"What does this sign tell you to expect?",
       a:["A bus depot","No buses allowed","A school bus stop somewhere ahead","A school bus stopped right now"],
       e:"It warns you in advance. The legal duty to stop comes only from the bus's own flashing red lights and stop arm." },
  fr:{ q:"À quoi ce panneau vous dit-il de vous attendre ?",
       a:["Un dépôt d'autobus","Aucun autobus permis","Un arrêt d'autobus scolaire plus loin","Un autobus scolaire arrêté en ce moment"],
       e:"Il vous avertit à l'avance. L'obligation légale d'arrêter vient uniquement des feux rouges clignotants et du bras d'arrêt de l'autobus." },
  c:2 },

{ id:"abs72", sec:"signs", sign:"warn-bicycle",
  en:{ q:"What should you do after this sign?",
       a:["Sound your horn","Speed up past the area","Drive on the shoulder","Expect cyclists and leave them at least a metre when passing"],
       e:"Cyclists may be hard to see against a busy background. Slow down, look twice and change lanes to pass where you can." },
  fr:{ q:"Que devriez-vous faire après ce panneau ?",
       a:["Klaxonner","Accélérer pour passer le secteur","Rouler sur l'accotement","Vous attendre à des cyclistes et leur laisser au moins un mètre en dépassant"],
       e:"Les cyclistes peuvent être difficiles à voir sur un fond chargé. Ralentissez, regardez deux fois et changez de voie pour dépasser quand c'est possible." },
  c:3 },

{ id:"abs73", sec:"signs", sign:"warn-t-intersection",
  en:{ q:"What does this sign tell you about the road ahead?",
       a:["It ends and you must turn left or right","It becomes one way","It narrows","A traffic light is coming"],
       e:"The road you are on stops at another road. Slow early — a T intersection at speed is a common single-vehicle crash." },
  fr:{ q:"Que vous indique ce panneau au sujet de la route devant ?",
       a:["Elle se termine et vous devrez tourner à gauche ou à droite","Elle devient à sens unique","Elle se rétrécit","Un feu de circulation approche"],
       e:"La route où vous êtes se termine à une autre route. Ralentissez tôt : une intersection en T abordée trop vite est une cause fréquente de sortie de route." },
  c:0 },

{ id:"abs74", sec:"signs", sign:"warn-narrow-lane",
  en:{ q:"What happens to the road after this sign?",
       a:["It is closed","It becomes narrower","It becomes wider","It splits in two"],
       e:"Less room means less margin for error. Ease off and keep your wheels centred in your own lane." },
  fr:{ q:"Qu'arrive-t-il à la route après ce panneau ?",
       a:["Elle est fermée","Elle se rétrécit","Elle s'élargit","Elle se divise en deux"],
       e:"Moins d'espace signifie moins de marge d'erreur. Levez le pied et gardez vos roues centrées dans votre voie." },
  c:1 },

{ id:"abs75", sec:"signs", sign:"warn-school-crossing",
  en:{ q:"When may you drive on after a crossing guard has stepped into the road?",
       a:["As soon as the guard waves","After counting to three","Once the children and the guard are back on the sidewalk","As soon as the children are past your lane"],
       e:"Everyone must be clear of the road, guard included. This is one of the most heavily penalised offences anywhere in Canada." },
  fr:{ q:"Quand pouvez-vous repartir après qu'un brigadier s'est avancé sur la route ?",
       a:["Dès que le brigadier fait signe","Après avoir compté jusqu'à trois","Une fois que les enfants et le brigadier sont revenus sur le trottoir","Dès que les enfants ont quitté votre voie"],
       e:"Tout le monde doit avoir quitté la chaussée, brigadier compris. C'est l'une des infractions les plus sévèrement punies au Canada." },
  c:2 },

{ id:"abs76", sec:"signs", sign:"warn-checkerboard",
  en:{ q:"What is this black and yellow checkerboard telling you?",
       a:["A rest stop is ahead","Construction begins in 1 km","Parking is permitted","The road changes direction sharply right here"],
       e:"It marks the hazard itself. If you can read it clearly you should already be slowing down." },
  fr:{ q:"Que vous indique ce damier noir et jaune ?",
       a:["Une halte routière se trouve devant","Des travaux commencent dans 1 km","Le stationnement est permis","La route change brusquement de direction juste ici"],
       e:"Il marque le danger lui-même. Si vous le lisez clairement, vous devriez déjà être en train de ralentir." },
  c:3 },

{ id:"abs77", sec:"signs", sign:"warn-chevron",
  en:{ q:"What do a series of these chevrons show you?",
       a:["Which way the road bends, and how sharply","Where to park","The distance to the next town","A cycling route"],
       e:"They line the outside of a curve. The more tightly they are spaced, the sharper the bend." },
  fr:{ q:"Que vous montre une série de ces chevrons ?",
       a:["De quel côté la route tourne, et à quel point","Où stationner","La distance jusqu'au prochain village","Un itinéraire cyclable"],
       e:"Ils bordent l'extérieur d'une courbe. Plus ils sont rapprochés, plus le virage est prononcé." },
  c:0 },

{ id:"abs78", sec:"signs", sign:"warn-right-lane-ends",
  en:{ q:"You are in the right lane at this sign. What is the correct move?",
       a:["Stay right to the very end","Signal and merge left early, matching the speed of traffic","Stop and wait","Speed past everyone"],
       e:"Merge while you still have room and a safe gap. Leaving it to the last metre is what turns a slow-down into a stop." },
  fr:{ q:"Vous êtes dans la voie de droite à ce panneau. Quelle est la bonne manœuvre ?",
       a:["Rester à droite jusqu'au bout","Signaler et vous rabattre à gauche tôt, en ajustant votre vitesse à la circulation","Vous arrêter et attendre","Doubler tout le monde"],
       e:"Rabattez-vous pendant qu'il vous reste de la place et un espace sécuritaire. Attendre le dernier mètre transforme un ralentissement en arrêt." },
  c:1 },

{ id:"abs79", sec:"signs", sign:"warn-divided-ends",
  en:{ q:"What must you be ready for just past this sign?",
       a:["A toll booth","A school zone","Oncoming traffic in the lane beside you","A gravel surface"],
       e:"The median is ending. Keep well right and do not begin a pass unless you can see the whole road ahead is clear." },
  fr:{ q:"À quoi devez-vous être prêt juste après ce panneau ?",
       a:["Un poste de péage","Une zone scolaire","De la circulation en sens inverse dans la voie voisine","Une surface de gravier"],
       e:"Le terre-plein se termine. Tenez bien votre droite et n'amorcez pas de dépassement sans voir que toute la route devant est libre." },
  c:2 },

{ id:"abs80", sec:"signs", sign:"temp-survey",
  en:{ q:"What is happening where this orange sign is posted?",
       a:["A speed camera is running","A parade is passing","A weather station is measuring","A crew is working on or beside the road"],
       e:"Orange means temporary. Slow down, watch for people close to the driving lane, and expect equipment on the shoulder." },
  fr:{ q:"Que se passe-t-il là où ce panneau orange est installé ?",
       a:["Un radar photo est en fonction","Un défilé passe","Une station météo prend des mesures","Une équipe travaille sur la route ou à côté"],
       e:"L'orange signifie temporaire. Ralentissez, surveillez les personnes près de la voie de circulation et attendez-vous à de l'équipement sur l'accotement." },
  c:3 },

/* ---------- Alberta-specific rules ---------- */

{ id:"abr61", sec:"rules", topic:"licensing",
  en:{ q:"How many demerit points may an Alberta Class 7 learner accumulate before suspension?",
       a:["8", "15", "4", "20"],
       e:"A learner is suspended at 8 points, half the 15 allowed to a fully licensed driver. New drivers get much less room for error." },
  fr:{ q:"Combien de points d'inaptitude un apprenti conducteur de classe 7 en Alberta peut-il accumuler avant une suspension ?",
       a:["8","15","4","20"],
       e:"Un apprenti est suspendu à 8 points, la moitié des 15 permis à un conducteur pleinement titulaire. Les nouveaux conducteurs ont beaucoup moins de marge." },
  c:0 },

{ id:"abr62", sec:"rules", topic:"licensing",
  en:{ q:"Who may supervise an Alberta Class 7 learner?",
       a:["Anyone over 16","Someone over 18 holding a full Class 5 licence or higher","Any licensed driver","A parent only"],
       e:"The supervisor must be over 18, hold a full Class 5 or better, and sit in the front passenger seat beside you." },
  fr:{ q:"Qui peut superviser un apprenti conducteur de classe 7 en Alberta ?",
       a:["Toute personne de plus de 16 ans","Une personne de plus de 18 ans détenant un permis complet de classe 5 ou supérieur","Tout conducteur titulaire d'un permis","Un parent seulement"],
       e:"Le superviseur doit avoir plus de 18 ans, détenir un permis complet de classe 5 ou supérieur, et s'asseoir sur le siège du passager avant à côté de vous." },
  c:1 },

{ id:"abr63", sec:"rules", topic:"licensing",
  en:{ q:"Between which hours may an Alberta Class 7 learner not drive?",
       a:["10 p.m. and 4 a.m.","There is no restriction","Midnight and 5 a.m.","11 p.m. and 6 a.m."],
       e:"Learners must stay off the road from midnight to 5 a.m., the hours when visibility, fatigue and impaired drivers combine worst." },
  fr:{ q:"Entre quelles heures un apprenti de classe 7 en Alberta ne peut-il pas conduire ?",
       a:["22 h et 4 h","Il n'y a aucune restriction","Minuit et 5 h","23 h et 6 h"],
       e:"Les apprentis doivent rester hors de la route de minuit à 5 h, les heures où la visibilité, la fatigue et les conducteurs aux facultés affaiblies se combinent le plus mal." },
  c:2 },

{ id:"abr64", sec:"rules", topic:"licensing",
  en:{ q:"How many people may ride in an Alberta learner's vehicle?",
       a:["Two at most","Only the supervisor","Any number","No more people than there are seat belts"],
       e:"Every occupant needs a working seat belt, so the seat belt count is the passenger limit." },
  fr:{ q:"Combien de personnes peuvent prendre place dans le véhicule d'un apprenti en Alberta ?",
       a:["Deux au maximum","Seulement le superviseur","N'importe quel nombre","Pas plus de personnes qu'il n'y a de ceintures de sécurité"],
       e:"Chaque occupant doit disposer d'une ceinture de sécurité fonctionnelle : le nombre de ceintures est donc la limite de passagers." },
  c:3 },

{ id:"abr65", sec:"rules", topic:"impaired",
  en:{ q:"What blood alcohol level must an Alberta learner have while driving?",
       a:["Zero at all times","Under .05","Under .08","No rule applies to learners"],
       e:"Zero, every time you drive, for the whole graduated licensing programme. Alberta's zero tolerance programme applies on top of the criminal limit." },
  fr:{ q:"Quel taux d'alcool dans le sang un apprenti conducteur albertain doit-il avoir au volant ?",
       a:["Zéro en tout temps","Moins de 0,05","Moins de 0,08","Aucune règle ne s'applique aux apprentis"],
       e:"Zéro, chaque fois que vous conduisez, pendant tout le programme de permis par étapes. Le programme de tolérance zéro de l'Alberta s'ajoute à la limite criminelle." },
  c:0 },

{ id:"abr66", sec:"rules", topic:"conditions",
  en:{ q:"Alberta gets sudden ground blizzards on open prairie. What is the safest response?",
       a:["Stop in the driving lane","Slow down, turn on low beams, and pull well off the road if you cannot see","Speed up to get through it","Turn on high beams"],
       e:"Visibility can drop to nothing in seconds. If you must stop, get right off the road, keep your lights on and stay belted in." },
  fr:{ q:"L'Alberta connaît des poudreries soudaines en plaine. Quelle est la réaction la plus sécuritaire ?",
       a:["Vous arrêter dans la voie de circulation","Ralentir, allumer les feux de croisement et vous ranger bien à l'écart si vous ne voyez plus","Accélérer pour traverser","Allumer les feux de route"],
       e:"La visibilité peut tomber à zéro en quelques secondes. Si vous devez arrêter, quittez complètement la route, gardez vos feux allumés et restez attaché." },
  c:1 },

{ id:"abr67", sec:"rules", topic:"conditions",
  en:{ q:"Why is a chinook a hazard for Alberta drivers?",
       a:["It causes flooding","It has no effect on driving","Melting then re-freezing leaves ice on the road, often overnight","It brings heavy fog only"],
       e:"A warm chinook melts snow during the day; when the temperature drops again the meltwater freezes into a sheet of ice." },
  fr:{ q:"Pourquoi un chinook est-il un danger pour les conducteurs albertains ?",
       a:["Il cause des inondations","Il n'a aucun effet sur la conduite","La fonte suivie d'un regel laisse de la glace sur la route, souvent la nuit","Il n'apporte que du brouillard épais"],
       e:"Un chinook doux fait fondre la neige le jour ; quand la température rebaisse, l'eau de fonte gèle et forme une plaque de glace." },
  c:2 },

{ id:"abr68", sec:"rules", topic:"sharing",
  en:{ q:"You meet a wide farm implement on a rural Alberta road. What should you do?",
       a:["Pass immediately","Sound your horn and follow closely","Drive onto the shoulder to get by","Slow right down and pass only when you can see far ahead"],
       e:"Farm machinery is wide, slow and blocks your view. It may also turn left into a field entrance with little warning." },
  fr:{ q:"Vous croisez une machine agricole large sur une route rurale albertaine. Que devriez-vous faire ?",
       a:["Dépasser tout de suite","Klaxonner et suivre de près","Rouler sur l'accotement pour passer","Ralentir nettement et ne dépasser que lorsque vous voyez loin devant"],
       e:"Les machines agricoles sont larges, lentes et masquent la vue. Elles peuvent aussi tourner à gauche vers l'entrée d'un champ sans grand préavis." },
  c:3 },

{ id:"abr69", sec:"rules", topic:"collisions",
  en:{ q:"A deer crosses in front of you on a dark Alberta highway. What is usually safest?",
       a:["Brake firmly in a straight line rather than swerving","Swerve hard to miss it","Speed up","Turn off your headlights"],
       e:"Swerving at highway speed often ends in the ditch or in oncoming traffic. Brake hard and straight, and expect more animals behind the first." },
  fr:{ q:"Un chevreuil traverse devant vous sur une route sombre de l'Alberta. Quelle est habituellement la conduite la plus sûre ?",
       a:["Freiner fermement en ligne droite plutôt que de faire une embardée","Faire une embardée pour l'éviter","Accélérer","Éteindre vos phares"],
       e:"Une embardée à vitesse d'autoroute finit souvent dans le fossé ou face à la circulation. Freinez fort et droit, et attendez-vous à d'autres animaux derrière le premier." },
  c:0 },

{ id:"abr70", sec:"rules", topic:"licence",
  en:{ q:"Why does Alberta hold new drivers to a lower demerit threshold than experienced ones?",
       a:["There is no reason given","New drivers crash more often, so the system catches risky habits early","To raise more money","Because their vehicles are older"],
       e:"Graduated licensing is built on evidence: restrictions and a tighter point limit while experience is low, then full privileges once it is earned." },
  fr:{ q:"Pourquoi l'Alberta impose-t-elle aux nouveaux conducteurs un seuil de points plus bas qu'aux conducteurs expérimentés ?",
       a:["Aucune raison n'est donnée","Les nouveaux conducteurs ont plus d'accidents : le système repère tôt les habitudes risquées","Pour percevoir plus d'argent","Parce que leurs véhicules sont plus vieux"],
       e:"Le permis par étapes repose sur des données : des restrictions et une limite de points plus serrée tant que l'expérience est faible, puis tous les privilèges une fois acquise." },
  c:1 }

